from (values
  (1, '12-urban-cafe-breakfast-and-dinner-movie-night-cocktail-bar-canggu', 'why_its_here', (select count(*)::int from venues where slug = '12-urban-cafe-breakfast-and-dinner-movie-night-cocktail-bar-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ea13656751b5d2940200b867ae2c2cf7'), md5('A cafe and cocktail bar on Jalan Pantai Batu Mejan, open 8am to midnight daily. The main menu goes from pasta and risotto to schnitzel and seafood, with a rib eye steak. Brunch, the bar and wine cocktails have their own menus. Book through the site or Chope.') = '537e6548bdd3ceef4cb069ee5460303b'),
  (2, '7am-bakers-umalas', 'why_its_here', (select count(*)::int from venues where slug = '7am-bakers-umalas' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '740ebfabb748362de4a6b060206d19be'), md5('On Jalan Bumbak Dauh, 7AM Bakers runs its Umalas outlet as a bakery and all-day cafe. The brand has seven outlets across Bali and Jakarta, and this one''s page describes freshly baked artisan pastries, specialty coffee and international dishes. Tables book online; GoFood and GrabFood deliver.') = '76d8ecc3ff09166782c7b83e437b2667'),
  (3, '7am-bakers-umalas', 'not_for', (select count(*)::int from venues where slug = '7am-bakers-umalas' and status = 'active' and publication_status = 'published' and md5(not_for) = 'fe78f62e7461d0bc4e6bd19fb76ba068'), md5('A late dinner: it keeps daytime hours and closes in the evening') = 'f691352208d56d6c492f37ff23cc9f9c'),
  (4, 'adda-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'adda-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '03a1ef1736b752ad4ea9697528ff8b04'), md5('A yoga studio above the Awan co-working space on Jalan Kayu Manis in Canggu. Classes run from vinyasa and ashtanga to hatha, yin and restorative, with pranayama and meditation alongside sound healing and kundalini. The studio also runs 200- and 300-hour teacher trainings.') = 'cac4b2bf037ce332c837c772710e30b0'),
  (5, 'adda-yoga', 'best_for', (select count(*)::int from venues where slug = 'adda-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a5893be9f21ba048769d9ac29020116f'), md5('A walk-in class, with drop-in rates tiered by tourist visa, KITAS or Indonesian ID') = 'a42af04a5169082c5102544fdc967ccd'),
  (6, 'adda-yoga', 'not_for', (select count(*)::int from venues where slug = 'adda-yoga' and status = 'active' and publication_status = 'published' and md5(not_for) = '6107dde0e294073125ed46da67b63019'), md5('Booking or paying online: you register and pay at the counter') = '9c6e0c7447a7d0dde5ea27c853b5bffe'),
  (7, 'amo-spa-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'amo-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '58a29e7100e24a36eb079c6858e7c1d9'), md5('A Batu Bolong wellness spa, open since 2008, that pairs traditional Balinese treatments with AMO Baths. The baths are a self-guided recovery circuit: sauna, ice bath and mineral soak. There are clinical facials too, and a cold-pressed juice cafe.') = '0dfeecdd19ac544b57a2a2349e0b72f4'),
  (8, 'amo-spa-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'amo-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '3db6483456414f228e0d327c3a73953e'), md5('A slow, personalized massage or facial, or the hot-cold AMO Baths circuit') = '5359394625b889b691fa45e91805a9ff'),
  (9, 'ashe-grill-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'ashe-grill-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1836c6294674eb003334830c6573249c'), md5('Ashe runs a wood-fired grill and bar on Jl. Pantai Pererenan, open evenings only. It opened in December 2025 with a kitchen built, by its own account, around live fire and Global South cooking traditions. The name is a Yoruba concept meaning life force.') = '7e971b30fc5407c02a1452244c4f7f9b'),
  (10, 'ashe-grill-and-bar', 'best_for', (select count(*)::int from venues where slug = 'ashe-grill-and-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b0ca21f0fa761deebe68310c5d5bc5f2'), md5('Late dinners of wood-fired grill cooking on the Pererenan beach road') = '7ef03a50e680528666d9552e15ce089d'),
  (11, 'ashe-grill-and-bar', 'not_for', (select count(*)::int from venues where slug = 'ashe-grill-and-bar' and status = 'active' and publication_status = 'published' and md5(not_for) = 'aa8ef2f904598b8cc1677793ad55998a'), md5('Lunch: it serves dinner only, and the kitchen opens at 5pm') = '44c20800e3b3db7597ad68d4a9a66e7a'),
  (12, 'aunty-ji-s', 'why_its_here', (select count(*)::int from venues where slug = 'aunty-ji-s' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'bc3e197de2a2946bc74b24702966893d'), md5('Aunty Ji''s, a Mumbai-inspired Indian kitchen on Batu Bolong, cooks from family aunty recipes. Expect curries, biryani, naan and street food such as vada pav. It stays open to midnight and delivers through GoFood and GrabFood.') = 'c4d168d46421ae643acd88875c7db5a4'),
  (13, 'aunty-ji-s', 'best_for', (select count(*)::int from venues where slug = 'aunty-ji-s' and status = 'active' and publication_status = 'published' and md5(best_for) = '50b0469beb2fe61c71f4fa358abc6f0c'), md5('A craving for Indian comfort food, from curries and biryani to vada pav, or a weekend brunch') = 'c049eb2a797bfcbc6df81bf7f0c40fbb'),
  (14, 'aunty-ji-s', 'not_for', (select count(*)::int from venues where slug = 'aunty-ji-s' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e59a8e8e7a611fd5444cfd576992df9c'), md5('A quiet meal. The room is casual and built around sharing plates') = 'eee5d17e18b7befacf630c802e537a14'),
  (15, 'baked-berawa', 'why_its_here', (select count(*)::int from venues where slug = 'baked-berawa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ae17af7c7f0d59619acfadb8bfc8c897'), md5('One of several BAKED. bakehouses in Bali, this one on Jl. Raya Semat in Berawa (Tibubeneng) pairs artisanal baking with specialty coffee. The brand''s site lists gourmet breads and laminated pastries for breakfast, brunch and lunch.') = '754838cb99c8eb341e62317925debb03'),
  (16, 'baked-berawa', 'best_for', (select count(*)::int from venues where slug = 'baked-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e859f000cd54cc6adce27ef0bd4548c9'), md5('A morning meet-up over brunch, coffee and pastries') = '6e58072d5d691df233b420b607b5b2a9'),
  (17, 'baked-berawa', 'not_for', (select count(*)::int from venues where slug = 'baked-berawa' and status = 'active' and publication_status = 'published' and md5(not_for) = '023e9edabce63eb2ced40b9bf6b00857'), md5('Dinner, because it closes at 7pm') = '6d00029651e2174f7d4bc3e3d7efe8b8'),
  (18, 'baked-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'baked-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9671897f1fd6f08aa012f419e262f0c4'), md5('The Pererenan branch of BAKED., an artisanal bakehouse and specialty-coffee brand with several locations around Bali. It is on Jl. Pantai Pererenan, and its website describes gourmet breads and laminated pastries from breakfast through brunch to lunch.') = '67e160a2dbf6f7ab8de7ff617679555d'),
  (19, 'baked-pererenan', 'best_for', (select count(*)::int from venues where slug = 'baked-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = '5c12c2ac85234663b364789772f7ab0d'), md5('Morning brunch, or a pastry-and-coffee stop on the Pererenan beach road') = '5a2b9b3d44e44016e92bd26d2cc72a86'),
  (20, 'bali-barber-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'bali-barber-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a00f0b37a17be817eed926bf2174548b'), md5('The Canggu branch of the Bali Barber chain, a barber for men. It does scissor cuts, clipper fades, beard work and classic hot-towel shaves.') = '44033af4aecbaa5a0b83fa05c41642ed'),
  (21, 'bali-barber-canggu', 'best_for', (select count(*)::int from venues where slug = 'bali-barber-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '33eb0613e22bd4c23ac669d65f60079a'), md5('Men after a walk-in cut, fade or shave in central Canggu') = '3d2499e996497a61d8c93423ea3ede33'),
  (22, 'bali-buda-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'bali-buda-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8370907c4de279769a0d59be7cf9ac22'), md5('Bali Buda has been on the island for over 25 years; its Canggu branch is an organic wholefoods cafe and shop. The menu covers breakfasts, bowls, salads and mains, plus bakery items and a list of juices and smoothies.') = 'c74492f7f15938f16739eead21354812'),
  (23, 'bali-buda-canggu', 'best_for', (select count(*)::int from venues where slug = 'bali-buda-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '3e4b9aad690a3809427272fa74c9caa0'), md5('A wholefoods brunch or lunch with vegan, gluten-free and paleo options marked, then a raid on the organic shop') = '7574a1df70b37a421531503b98be2c2a'),
  (24, 'bali-mma-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'bali-mma-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '391da8f84715f9456f0539261be0b14d'), md5('On Jalan Raya Padonan, Bali MMA runs a combat-sports gym for all levels, kids classes included. Boxing, Muay Thai, BJJ, no-gi grappling and MMA sparring run daily: 6am-10pm on weekdays, 7am-6pm at weekends. There''s a weight room, an ice bath and a sauna.') = '54cae092d49cccce089278340d4acf50'),
  (25, 'bali-mma-canggu', 'best_for', (select count(*)::int from venues where slug = 'bali-mma-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '03e5f273fe7dde3b85a6850b3b595364'), md5('A fight-training session at any level on a day pass, from 240K') = '3c383b55feb8338c3d6f0f6849752b23'),
  (26, 'bar-vera-bistro-and-wine-bar', 'why_its_here', (select count(*)::int from venues where slug = 'bar-vera-bistro-and-wine-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '149eb1637b65f819ce2e03ddff71bcd1'), md5('A 65-seat European bistro and wine bar on Jl. Pantai Pererenan, cooking produce-driven food with classic technique. The wine list is European-focused, cocktails and aperitifs have their own card, and lunch runs to breakfast plates and coffee. Bookings go through SevenRooms on the venue''s site.') = '990d41079f3d7119a79310a0c7fc28af'),
  (27, 'bar-vera-bistro-and-wine-bar', 'best_for', (select count(*)::int from venues where slug = 'bar-vera-bistro-and-wine-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '4fff2b48b8d7493cadec7cecf01c5641'), md5('European wine and bistro plates over a date night or late dinner') = '21c6ce7b4947f3a0e659dd7d4a00bd54'),
  (28, 'beach-boy-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'beach-boy-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a21b8ed49fd8d44ce05c1d601f3a3a46'), md5('A restaurant and cocktail bar on Jl. Munduk Catu seating up to 132 across five indoor and outdoor areas, rooftop included. The kitchen does steaks, seafood and pasta, with a vegan list; the cocktail and mocktail list is long. Happy hour (4-7pm daily): buy two cocktails, get one free.') = '7ac617a50ef271513d1712955aaba771'),
  (29, 'beach-boy-canggu', 'best_for', (select count(*)::int from venues where slug = 'beach-boy-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '7481c670cfd7c25ceacefeeeefc5d8b2'), md5('A date night, a group dinner or a birthday, with live acoustic sessions on Saturdays') = '8ec28557b71f46549a175d7f6d3a6a2b'),
  (30, 'beach-boy-canggu', 'not_for', (select count(*)::int from venues where slug = 'beach-boy-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c2517261447632f0d0c2e54ab05f8355'), md5('A quiet solo laptop session or a fast grab-and-go lunch: the restaurant seats up to 132 across five areas') = '04a75b997adf84a674750afe97227fd2'),
  (31, 'beachtown-grocer', 'why_its_here', (select count(*)::int from venues where slug = 'beachtown-grocer' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1e1cef99eda65e4cdc6f1307a831aa44'), md5(U&'Beachtown Grocer is a New York deli-style caf\00E9 and grocery counter inside Secana Beachtown in Berawa, open 6am to 11pm. The daily special rotates and costs 99K. Sit indoors or alfresco, or take breakfast and groceries to go.') = 'a34ef34c4d9cc142fc3c828c00fc2340'),
  (32, 'beachtown-grocer', 'best_for', (select count(*)::int from venues where slug = 'beachtown-grocer' and status = 'active' and publication_status = 'published' and md5(best_for) = '88dd53c1e44d6ca390688eea673c480e'), md5('A deli breakfast or the 99K daily special, with groceries to grab on the way out') = 'b76ce0443e90e7bbcceb908b17ac04ee'),
  (33, 'billy-ho-japanese-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'billy-ho-japanese-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ae6456641f6b927f4b47752acce6376b'), md5('Billy Ho pairs a modern Japanese kitchen with a cocktail bar on Batu Bolong, open through a long run from lunch to dinner. Yakitori, sushi and shareable plates make up the menu, the cocktails get hand-carved ice, and DJs play at weekends.') = '5564b8c06f381feeee3ffd05105a2d7a'),
  (34, 'billy-ho-japanese-restaurant', 'best_for', (select count(*)::int from venues where slug = 'billy-ho-japanese-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dcd033d2da135b3c7d716bef962059dc'), md5('Japanese small plates and cocktails over a long lunch that rolls into dinner') = '7f5cb41d08772589a23b74c1f7c00c90'),
  (35, 'body-factory-bali-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'body-factory-bali-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8510ba96981bf2a7c3019d921cd815e1'), md5('At Jl. Nelayan No.27, Body Factory''s large gym opens 6am-10pm daily. More than 50 classes cover HYROX, strength, boxing, mat pilates, mobility and yoga. Recovery runs from hot tub and sauna to ice bath and cold plunge, with a pool too.') = '4c4e567ea9bd478200e49618ad69c3b1'),
  (36, 'body-factory-bali-canggu', 'best_for', (select count(*)::int from venues where slug = 'body-factory-bali-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '28108ac1d717a738ea5e039a0337458e'), md5('A gym or HYROX session on a 1, 3, 7 or 14-day pass or a four-week membership') = '63bce3a65134cd9344b6e66a449b101b'),
  (37, 'body-factory-bali-canggu', 'not_for', (select count(*)::int from venues where slug = 'body-factory-bali-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a931b59933b3d932de083e51ba130771'), md5('A gym-only pass if you want the ice bath and sauna, because recovery is a separate tier') = '4212f17977cb0872619f15fbf703e9d2'),
  (38, 'body-factory-bali-recovery-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'body-factory-bali-recovery-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '032c57bd46723bc9225bd28daabed2da'), md5('The recovery wing of Body Factory in Nelayan, open 6am to 10pm. Ice baths, sauna and bodywork here are aimed at recovery after training.') = '3513b953a8876d0c84409667287a5bff'),
  (39, 'body-factory-bali-recovery-canggu', 'best_for', (select count(*)::int from venues where slug = 'body-factory-bali-recovery-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e0363b6ae94264a5ee0c83d091e44efd'), md5('After training, when you want cold plunge and sauna rather than a traditional spa') = 'fc2acd9ce4dcd2e49aaa65b7dd8d712d'),
  (40, 'bonito-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'bonito-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f10a3d8f8124b80ec1e4cca848b12f6b'), md5('Bonito is a seafood and Mediterranean kitchen on the roof of the Kleo Hotel in Kerobokan Kelod, run by the team behind MAURI Seminyak. Pasta is handmade and seafood comes in fresh daily. Thursday is an all-you-can-eat oyster-and-pasta night.') = '50c17fbcc6fbe0d0950af793bbaf0cc6'),
  (41, 'bonito-restaurant', 'best_for', (select count(*)::int from venues where slug = 'bonito-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c498eb5a30c726ca7501856e2ab621c0'), md5('A rooftop dinner of Mediterranean seafood and pasta, shared or as a tasting menu') = 'e43253cb503a4aef923fc4967ec9c486'),
  (42, 'bonito-restaurant', 'not_for', (select count(*)::int from venues where slug = 'bonito-restaurant' and status = 'active' and publication_status = 'published' and md5(not_for) = 'db690986031ae2c766307c754b2e0de6'), true),
  (43, 'bottega-italiana', 'why_its_here', (select count(*)::int from venues where slug = 'bottega-italiana' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'da05c056ba09170e4d7d777d50a4b6e1'), md5('Gourmet Italian home-cooking from the Zibiru group (running since 2015), making its own fresh pasta, bread, cheese and desserts.') = '8a67215648bad98e701cde39d2086580'),
  (44, 'bottega-italiana', 'best_for', (select count(*)::int from venues where slug = 'bottega-italiana' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b9be4104f83d7417141cf2a931c259ee'), md5('Families and groups sharing pasta') = 'ff97ccb26d958df51ba7464d7f9a960d'),
  (45, 'bottega-italiana', 'not_for', (select count(*)::int from venues where slug = 'bottega-italiana' and status = 'active' and publication_status = 'published' and md5(not_for) = 'eddae1ef8dec237ced9896bc1fd7ae41'), md5(U&'Breakfast \2014 the kitchen opens at 11am.') = '25e343cc0be6ef66c24f50c62416c01b'),
  (46, 'brother-gym', 'why_its_here', (select count(*)::int from venues where slug = 'brother-gym' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ac72d4dc4bdf1d7d561f45d8f7f872b1'), md5('Weights and machines fill Brother Gym at Jl. Raya Babakan No.14, open 6.30am-10pm daily. Day passes are sold, and so are weekly, monthly and annual memberships. Its counter adds protein shakes and scoops of supplements to the juice and coffee.') = 'f7160c93196667f12863759b9d826168'),
  (47, 'brother-gym', 'best_for', (select count(*)::int from venues where slug = 'brother-gym' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c0c2399e4bacbc8447a99bbf343c1c3f'), md5('A low-cost weights session on a day pass, with personal training by the session or in packs') = '89f522f27283ad3c9ba606d659b05078'),
  (48, 'brother-gym', 'not_for', (select count(*)::int from venues where slug = 'brother-gym' and status = 'active' and publication_status = 'published' and md5(not_for) = '110abb8d95c295157755e83b7b8c24eb'), md5('Paying for the day pass and nothing else: a first visit adds a one-off 30K admin fee, and the locker key needs a 50K deposit') = 'f845de23d52644931f7cb1bc6a6193ac'),
  (49, 'brunch-club-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'brunch-club-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '96a2aeb80d9b9eb237a4539c570c8bbb'), md5('Brunch Club Bali''s Pererenan branch on Jl. Pantai Pererenan does brunch, lunch and cocktails all day. The group also has a Legian site. The house dish is Porncakes, a stacked pancake sold as a two- or three-stack in 14 flavours.') = '695b63b097c6d80ba1a3ae2d9087c365'),
  (50, 'brunch-club-pererenan', 'best_for', (select count(*)::int from venues where slug = 'brunch-club-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b795b8e51f08b762a26f30c4bbc5f632'), md5('Friends or family over an all-day brunch of big sweet and savoury plates, with cocktails') = 'acdfad9b4b722b2c0f42fcd6ed602f87'),
  (51, 'brunch-club-pererenan', 'not_for', (select count(*)::int from venues where slug = 'brunch-club-pererenan' and status = 'active' and publication_status = 'published' and md5(not_for) = 'd6ea24996f9c873e82142d0e35ef02af'), md5('Dinner: brunch and lunch are the only services listed') = 'ac579769cb37c6f3acab37df779892f3'),
  (52, 'cafe-del-mar-bali', 'why_its_here', (select count(*)::int from venues where slug = 'cafe-del-mar-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '72d275c5195a68474ed6a02a51bcd6cd'), md5(U&'Caf\00E9 del Mar''s Bali site, a beachfront club on Jl. Subak Sari in Tibubeneng, has an infinity pool, DJ sets and events. The kitchen calls itself premium casual dining from the Mediterranean Basin. Its desserts and cocktails are house creations. Open daily, 11:00 to 20:00.') = '476f05d4a079ed93fb7ecc6bba929b31'),
  (53, 'cafe-del-mar-bali', 'best_for', (select count(*)::int from venues where slug = 'cafe-del-mar-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '8212e685059f822f4fd6c7e8589bef4e'), md5('Sunset drinks or a pool day, Ibiza-style, with a group after the beach') = '0c35f99167226f9fbc31d0550c484fb1'),
  (54, 'cafe-del-mar-bali', 'not_for', (select count(*)::int from venues where slug = 'cafe-del-mar-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '608c993f8ae31b3b72f6a3ef8a6acaf1'), md5('A late night out, because it closes at 8pm daily') = 'a2bb9607dede652d3080e34efdcf7f31'),
  (55, 'canggu-club-tennis-centre', 'why_its_here', (select count(*)::int from venues where slug = 'canggu-club-tennis-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '27b47af4b53b621fd7ac610265cb9e5a'), md5('The tennis centre of FINNS Recreation Club, formerly the Canggu Club, on Jl. Pantai Berawa. It has three indoor floodlit courts on a Flexipave surface, plus a pro shop, cafe and bar. Coaches and hitting partners are on hand, ball boys too.') = 'e4e045cb2612be05da3f82f9be8074b3'),
  (56, 'canggu-club-tennis-centre', 'best_for', (select count(*)::int from venues where slug = 'canggu-club-tennis-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = '1dd5921ecfac40105a47847d587a166f'), md5('Tennis out of the sun on a floodlit court, on a day pass or a membership open to the public') = '969a6ae0ce9d5f960bef174b2f4143cf'),
  (57, 'canggu-yoga-centre-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'canggu-yoga-centre-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '558b59b564d45d2f4a1d47bff799f5e7'), md5('From early morning, Canggu Yoga Centre teaches Ashtanga, hot yoga and hot-pilates-style HIIT at its Pererenan studio. Showers and a cafe are on site, as is gear. The published timetable shifts, so check the day''s classes before you go.') = 'c4f099aeaa195648cd21080f603187d5'),
  (58, 'canggu-yoga-centre-canggu', 'best_for', (select count(*)::int from venues where slug = 'canggu-yoga-centre-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '98d27d58360b3407eb70c2b8a0dfa24d'), md5('An accessible morning practice in Pererenan: Ashtanga, hot yoga or hot pilates') = '64389b3ec6bb7ac405d303b14413d320'),
  (59, 'canggu-yoga-centre-canggu', 'not_for', (select count(*)::int from venues where slug = 'canggu-yoga-centre-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '836701f1eba45ebfb69b8a8405c8e5c4'), md5('A fixed weekly routine: the published timetable shifts') = '17c40115a6a8715f9aaeed5e5c2097db'),
  (60, 'chow-chow-bali', 'why_its_here', (select count(*)::int from venues where slug = 'chow-chow-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a597ece8f9fbf283c5c5ecc36eaf6a5e'), md5('Chow Chow Bali is a contemporary Asian-fusion restaurant in Batu Bolong, open daily from late morning to midnight. The menu runs to sushi rolls, bao buns, slow-cooked pork ribs and poke bowls. Cocktails and a kids menu round it out.') = '8fb25acd257d86f1c1cec5e7b5db6bc1'),
  (61, 'chow-chow-bali', 'best_for', (select count(*)::int from venues where slug = 'chow-chow-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a668bdde0fde93cca10be72221ccefcb'), md5('From lunch to late night: Asian-fusion sushi, bao and poke bowls in Batu Bolong') = 'aed657679d336e32bc7abc5f847e3f03'),
  (62, 'como-beach-club-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'como-beach-club-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '58fd06f5169b7726feb89d3e655ca13f'), md5('The beach club and restaurant at COMO Uma Canggu, on the sand at Batu Mejan. It runs from breakfast to a 10pm dinner close with live music and DJ sets. Separate menus cover the main kitchen, a seafood BBQ and the COMO Shambhala Kitchen.') = 'b1b0a8da1077733a5da084b674d20692'),
  (63, 'como-beach-club-canggu', 'best_for', (select count(*)::int from venues where slug = 'como-beach-club-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'eb03c49e65b45125d922d549343cd4b4'), md5('A polished sunset dinner or special occasion by the ocean, or a leisurely family-style Sunday brunch at 680K per person') = '3c5381b9d5bf29ea15e1b817b12828b0'),
  (64, 'como-beach-club-canggu', 'not_for', (select count(*)::int from venues where slug = 'como-beach-club-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e6169b4293fcb8ff3f0310211a6b74db'), md5('Walking in unbooked, because guests not staying at COMO Uma Canggu need a reservation') = '9033f394feac964d35bf573940e52b40'),
  (65, 'como-uma-canggu-wellness-spa-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'como-uma-canggu-wellness-spa-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3bb2b08e96bc2d46e83e942da4043a53'), md5('Near Echo Beach, COMO Uma Canggu keeps its spa and wellness floor, the COMO Shambhala Retreat, open 10am to 7pm. Massages and body therapies share the menu with Sundari and Guinot facials and nail care. Yoga, Pilates, meditation and breathwork are booked as private sessions.') = '98724c55fc0496a06a51041c87776993'),
  (66, 'como-uma-canggu-wellness-spa-canggu', 'best_for', (select count(*)::int from venues where slug = 'como-uma-canggu-wellness-spa-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '159bfe0df7899410d954088178be42fe'), md5('A 75-90 minute massage or a facial at a resort spa, or a private yoga or Pilates session') = '61bbae1744e5f7bb3bc3a594a08b785c'),
  (67, 'como-uma-canggu-wellness-spa-canggu', 'not_for', (select count(*)::int from venues where slug = 'como-uma-canggu-wellness-spa-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '78c7666442cf8f1e5ab18fad70f7982c'), md5('A treatment before 10am or after 7pm: it runs by appointment within those hours') = '42e2aa5c1cef034e5d9897cd16a778d3'),
  (68, 'copenhagen-cafe-berawa', 'why_its_here', (select count(*)::int from venues where slug = 'copenhagen-cafe-berawa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '649a80753688e7dcbfc276300bc75677'), md5(U&'A Nordic-inspired cafe and bakery in Berawa, built around a build-your-own feast: small dishes ticked off a menu card and served on a board. Sm\00F8rrebr\00F8d, lunch bowls and house-baked pastries fill out the menu. Feasts run 6am-6pm, and lunch starts at 12pm.') = '94eb42cb1b61070a9ad98ad9e9c2a947'),
  (69, 'copenhagen-cafe-berawa', 'best_for', (select count(*)::int from venues where slug = 'copenhagen-cafe-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = '2ef29154c89a670185ac18106927d619'), md5('Build-your-own Nordic breakfast boards from 6am, or daytime brunch and coffee') = '642a20c27ae38e6a7724f7e0d70effc9'),
  (70, 'copenhagen-cafe-berawa', 'not_for', (select count(*)::int from venues where slug = 'copenhagen-cafe-berawa' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c67a13536cda5b4a1795228aadc3b21a'), md5('Laptop work or dinner: the cafe is laptop-free and food stops at 6pm') = 'fefc470bd7bf92917fbdd926460db850'),
  (71, 'crate-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'crate-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ff323b4112f06fcd77450571b64e60a0'), md5('An industrial-style all-day breakfast place on Jl. Batu Bolong. The smoothie bowls are big, and the menu rotates, chalked on the wall behind the counter.') = '8644856c834a2725f0b0053e992f578f'),
  (72, 'crate-cafe', 'best_for', (select count(*)::int from venues where slug = 'crate-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '3208521b02e8751571f68bd395b10b5a'), md5('An affordable all-day brunch on Batu Bolong, straight after a surf') = 'c3ca21fa6f631565fde486268b7ae565'),
  (73, 'crate-cafe', 'not_for', (select count(*)::int from venues where slug = 'crate-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = '164dfd5faf5637e8d992dab57c4120ee'), md5('A quiet sit-down or laptop work, because the room is loud, crowded and high-turnover, busiest after a surf') = 'e26e058f5d47fe3d949c64f41f670e2f'),
  (74, 'cutiepai-nails', 'why_its_here', (select count(*)::int from venues where slug = 'cutiepai-nails' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8d6b16516191b4624dbafab079557065'), md5('CutiePai Nails is a home-based nail salon in Pererenan, minutes from central Canggu, open daily 9am-7pm by appointment. It specialises in BIAB, gel nails, extensions, manicures, pedicures and custom hand-painted nail art, and sanitises tools between clients. Home visits are an option too.') = '468c1c458ff328f76639322e31217491'),
  (75, 'cutiepai-nails', 'best_for', (select count(*)::int from venues where slug = 'cutiepai-nails' and status = 'active' and publication_status = 'published' and md5(best_for) = '705527cc0bfea596afbfd75cbf19bac7'), md5('A booked BIAB, gel or nail-art session in a small, private Pererenan setting') = 'f2d11a1637d1b6a8ed5f55aa6690080a'),
  (76, 'dandelion', 'why_its_here', (select count(*)::int from venues where slug = 'dandelion' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '707838d2ac961755f7047f61016e3b87'), md5('Casa Tua, an Indonesian restaurant on Batu Bolong, has cooked Balinese family recipes since 2014. The plant-filled room splits between open-air tables and cosy indoor nooks, and resident rabbits roam free. It used to trade as Dandelion; the team and menu have not changed.') = '1d97bacd841ec49d14136dc9c4a4d70c'),
  (77, 'dandelion', 'best_for', (select count(*)::int from venues where slug = 'dandelion' and status = 'active' and publication_status = 'published' and md5(best_for) = '2b460542773b25110feb1f792f282c87'), md5('Balinese home cooking over a romantic meal among plants, with resident rabbits') = '9798c05e3ab7ca607023556b4124d6e4'),
  (78, 'dandelion', 'not_for', (select count(*)::int from venues where slug = 'dandelion' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e055ffa7315c000b4e722debad1a98a2'), md5('Anyone who''d rather not share the floor with animals: free-running rabbits roam the dining area') = 'e29fb9cbc3d668b358b960d644cb54f7'),
  (79, 'desa-seni-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'desa-seni-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '53013360873414920356588e4f5449ec'), md5('Daily classes in an open-air wooden shala make up the yoga programme of Desa Seni, a village-style resort near Berawa.') = 'f2f52616e9348413a1adfd9c21aa99a0'),
  (80, 'desa-seni-yoga', 'best_for', (select count(*)::int from venues where slug = 'desa-seni-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '38db78fb61a002f687cc56cdec8b02cd'), md5(U&'A drop-in class in a garden setting, then a meal at the resort''s organic caf\00E9') = 'abca63675dd87163679a7e0f1df7195b'),
  (81, 'deus-ex-machina', 'why_its_here', (select count(*)::int from venues where slug = 'deus-ex-machina' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '29a767ac2c301da388e11557dd713294'), md5('On Jl. Pantai Batu Mejan, Deus''s flagship "Temple of Enthusiasm" pairs a Pan-Asian cafe and bar with a motorcycle workshop. A retail store, a gallery and a live-music venue share the site, open from morning coffee until late.') = '627533da2886345a79b806b76b0c79d4'),
  (82, 'deus-ex-machina', 'best_for', (select count(*)::int from venues where slug = 'deus-ex-machina' and status = 'active' and publication_status = 'published' and md5(best_for) = '7fb6f1cb8b98495311942233a3741344'), md5('Coffee and brunch by day, or a night of live music with a crowd') = '5bf9c483f500a24fcdcc0b3af35db7b7'),
  (83, 'downtown-kedungu-restaurant-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'downtown-kedungu-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'bcb4d7f3d092dc5c2c8a87e91fada415'), md5('Downtown Kedungu, a Latin American restaurant and bar at Kedungu beach in Tabanan, sits about twenty minutes up the coast from Canggu. Every day of the week brings a different themed special.') = '492d473a3a1fb04548cce176c84a62ea'),
  (84, 'downtown-kedungu-restaurant-and-bar', 'best_for', (select count(*)::int from venues where slug = 'downtown-kedungu-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '60df0f598b491cb94ee6ba2db59245a0'), md5('A trip up the coast for Latin American plates and the day''s themed special') = 'b9a7885a5bfc50bc422080d989268c68'),
  (85, 'downtown-kedungu-restaurant-and-bar', 'not_for', (select count(*)::int from venues where slug = 'downtown-kedungu-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(not_for) = 'f19c16d1a98eac981fb16de9c13a652b'), md5('A spontaneous Sunday. The roast sells out, and the site asks you to book ahead') = 'fec03c5a9337c5ba9c99598c7461321b'),
  (86, 'e-a-r-t-h-by-ulaman', 'why_its_here', (select count(*)::int from venues where slug = 'e-a-r-t-h-by-ulaman' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b076b7cce765ba65ac6c07638df5b66f'), md5('E.A.R.T.H is the bamboo-built restaurant and lounge of the Ulaman Eco Luxury Resort in Buwit, Tabanan. Chef Alvin cooks Balinese and Nusantara food, and Italian, Thai and international dishes too. Set options range from a chef''s selection to a waterfall-deck dinner.') = 'cc54b79855c364f9e398afc9ecb3f2a3'),
  (87, 'e-a-r-t-h-by-ulaman', 'best_for', (select count(*)::int from venues where slug = 'e-a-r-t-h-by-ulaman' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f7ef3f73c45bbad7f0c4934956939875'), md5('Balinese or Nusantara meals at the Ulaman eco resort, among jungle, river and waterfalls') = '734e603f53d8e3a792fb9c7b6bd174f9'),
  (88, 'ecosfera-yoga-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'ecosfera-yoga-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '6dad4856f56f3edab67f308dd668cb77'), md5('A yoga class by the water, near Batu Mejan and Echo Beach') = 'a863229b374ea6539ad72026824e0081'),
  (89, 'ele-restaurant-bar-and-terrace', 'why_its_here', (select count(*)::int from venues where slug = 'ele-restaurant-bar-and-terrace' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3cf57644fce91cd6505157760393260c'), md5('ELE keeps an all-day restaurant, bar and terrace on Jl. Pantai Batu Bolong in Canggu, serving breakfast through late dinner. It has no website, only a link page, so we have confirmed the format and the address but not the menu.') = 'bb199f08fccc8e790f98b08d3efbe2c2'),
  (90, 'ele-restaurant-bar-and-terrace', 'best_for', (select count(*)::int from venues where slug = 'ele-restaurant-bar-and-terrace' and status = 'active' and publication_status = 'published' and md5(best_for) = '988daf76ec20abd214f4c9bc01616d75'), md5('Any meal from breakfast to a late dinner on Batu Bolong') = 'e9d25ecc8e7144cb9221545d784f082e'),
  (91, 'espace-spa-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'espace-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '41330877cedf4f61aaf8fed1f2319152'), md5('Espace Spa, a day spa on Jl. Pura Batu Mejan near Batu Bolong, publishes its price list. It covers aromatherapy massage, body scrubs, wraps, facials, cream bath, manicures, pedicures and sugaring hair removal. It also runs private massage classes and sells massage tables and chairs.') = 'e724df5e2269366ed4f615937b149a64'),
  (92, 'espace-spa-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'espace-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '8d8659636b921bc85442f58d6db013d1'), md5('A fixed-price massage, scrub, facial or nail treatment booked online in Batu Bolong') = '3060fec4cca7bac107e34aeffb3c4fc6'),
  (93, 'estetica-belle', 'why_its_here', (select count(*)::int from venues where slug = 'estetica-belle' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3cba3d2422ae4b24ed793dd8cf21d363'), md5('Estetica Belle works from a beauty studio at Jl. Pantai Pererenan No.69. It does lashes, brows, nails, waxing, permanent make-up, skin needling and laser tattoo removal. Clinical facials use Dermalogica and Doctor Babor products, plus Mesoestetic. The skin-treatment price list is on its own site.') = '98c6b68f3bb1eedf6bf6cb470a9ad6a3'),
  (94, 'estetica-belle', 'best_for', (select count(*)::int from venues where slug = 'estetica-belle' and status = 'active' and publication_status = 'published' and md5(best_for) = '6e564a947bed3d49b80e28cf57a1dedd'), md5('Lashes, brows, nails, waxing and clinical facials in one Pererenan studio') = '2e5f13adfb34e6b95aeade1db7e614ac'),
  (95, 'estetica-belle', 'not_for', (select count(*)::int from venues where slug = 'estetica-belle' and status = 'active' and publication_status = 'published' and md5(not_for) = '75983a64eed44d26c33f719c69162865'), md5('An evening or walk-in treatment: it closes at 6pm daily and works by appointment') = 'aae23eb3342f6fcfe59f40085eace7d3'),
  (96, 'f45-training-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'f45-training-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd09614c3c52dbaff879735ea7e19d7b8'), md5('The Canggu studio of the global F45 franchise, at Jl. Pantai Batu Bolong No.83, running 45-minute classes. Its ClassPass schedule puts cardio on Mondays and Wednesdays and resistance on Tuesdays, Thursdays and Sundays. Fridays and Saturdays are hybrid sessions.') = '9e1b8dacb3b397d30270a8e19ab0d387'),
  (97, 'f45-training-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'f45-training-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '5e4fea7c3e86f8f1cc24ce562d2af597'), md5('A coached 45-minute class mixing HIIT, circuit and functional training') = '806bf0960d7d70d9fac0cb383f2788ad'),
  (98, 'f45-training-canggu-canggu', 'not_for', (select count(*)::int from venues where slug = 'f45-training-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e0c41a5aaf2d49e50fbcdb9a7549df3f'), md5('A spur-of-the-moment visit, because sessions run to a fixed timetable and must be booked in advance') = 'ce5ed33beff4e60e377a8467f68c9315'),
  (99, 'face-therapy-spa-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'face-therapy-spa-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '43c64671df1f9035645b79eafe15cb35'), md5('Face Therapy, a face-massage spa on Jl. Tukad Pingai in Pererenan, opens 8am to 10pm daily. Treatments cover gua sha, buccal sculpting, lymphatic work and jetlag recovery. Its Fresha listing says woman-owned and kid- and pet-friendly, and names a second branch in Umalas.') = 'a5ae511240a84c403ab95822d9b6d96d'),
  (100, 'face-therapy-spa-pererenan', 'best_for', (select count(*)::int from venues where slug = 'face-therapy-spa-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = '1b0eed3b7fa1020879a3e2b1f5686854'), md5('Gua sha and buccal sculpting, or a jetlag-recovery face treatment after a long flight') = '1de4c699c77db0234826067a911cf43f'),
  (101, 'face-therapy-spa-pererenan', 'not_for', (select count(*)::int from venues where slug = 'face-therapy-spa-pererenan' and status = 'active' and publication_status = 'published' and md5(not_for) = '1419a207fc12b2c15ec0a4d83e750fa1'), md5('A quick drop-in, since treatments are booked ahead and run 60-120 minutes') = '629d848ad1303ca48f989500e615524b'),
  (102, 'finns-beach-club', 'why_its_here', (select count(*)::int from venues where slug = 'finns-beach-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c41da63da6630bb9314a9a6fb5aff12c'), md5('On a 170m stretch of Berawa beachfront, FINNS Beach Club is a day club with three pools, including swim-up bars. There are many bars and kitchens, and a daily lineup of DJs and live vocalists. It is the high-energy, pool-party end of Canggu''s beach clubs.') = 'f0daf7101b949cf03da58045a4ed3a27'),
  (103, 'finns-beach-club', 'best_for', (select count(*)::int from venues where slug = 'finns-beach-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '8e3cb2fc100a6da37b54ae7dbde836e9'), md5('A lively, high-energy pool day and sunset party with a big group') = 'b1d5a4d69f2bff8afec4002505b48bda'),
  (104, 'finns-recreation-club-finns-lifestyle-village', 'why_its_here', (select count(*)::int from venues where slug = 'finns-recreation-club-finns-lifestyle-village' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '742d0f48cbc9fb73e9d68b47dd547d5d'), md5('FINNS Recreation Club is the large membership club at FINNS Lifestyle Village in Berawa. It has a full gym, an Olympic-sized pool, tennis and padel courts and a kids'' club. Recovery means ice baths and an infrared sauna plus compression therapy; the spa is full-service Balinese.') = 'ac28840cb7db3053f3faa227f4058176'),
  (105, 'finns-recreation-club-finns-lifestyle-village', 'best_for', (select count(*)::int from venues where slug = 'finns-recreation-club-finns-lifestyle-village' and status = 'active' and publication_status = 'published' and md5(best_for) = '9ae91bc8fb4ab524d5344613c70ab03d'), md5('Families and active travellers on a longer Canggu or Berawa stay, on a day pass or a membership') = 'fdcb56b4d6d6ff0fb6dd62616fca144f'),
  (106, 'finns-recreation-club-finns-lifestyle-village', 'not_for', (select count(*)::int from venues where slug = 'finns-recreation-club-finns-lifestyle-village' and status = 'active' and publication_status = 'published' and md5(not_for) = '18d5ea87d9bbd242df77544b5910c6cf'), md5('A quiet, intimate boutique spa. The club is big and has many facilities') = '5e646b0e4780a1624c341e6bd4812e56'),
  (107, 'fitness-plus-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'fitness-plus-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8aa2b10b995b693f4a6abfc7f5815449'), md5('Fitness Plus Canggu, part of the Indonesian Fitness Plus chain, runs a 24-hour gym at Jl. Tanah Barak No.19. Its branch site lists more than 100 machines. The eight group programmes are Les Mills BodyPump, RPM, BodyCombat and Ceremony; Positive Spin; Mat Pilates; yoga; and Zumba.') = '57cff9dac0312b9d61c376fe5b40a96a'),
  (108, 'fitness-plus-canggu', 'best_for', (select count(*)::int from venues where slug = 'fitness-plus-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a56cb11408c656f08ca08b62a18834b4'), md5('A workout at any hour, with a sauna, lockers, showers, towels and parking on site') = '2650b2ec85a8cb145625319500663a87'),
  (109, 'flex-gym-bali', 'why_its_here', (select count(*)::int from venues where slug = 'flex-gym-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1b5c71ff7b05828e9511183d8b9584ba'), md5('Flex Gym has a single location: a gym on Gang Heliconia, off Jl. Raya Canggu. Strength equipment, from squat racks to machines, shares the floor with treadmills, rowers and air bikes. Passes run from a single day to twelve months. It has lockers and changing rooms, and parking.') = 'f34007adb76060c526e94adf09909551'),
  (110, 'flex-gym-bali', 'best_for', (select count(*)::int from venues where slug = 'flex-gym-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e81848d038ddc0014483b2c83f157e17'), md5('Drop-in strength sessions on a 150K day pass, from 06:30 on weekdays') = 'c6d501fb353e17b58e23be8a64e0b4b2'),
  (111, 'flex-gym-bali', 'not_for', (select count(*)::int from venues where slug = 'flex-gym-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '5f27d4345252711d18dabfd4cfdae7be'), md5('An evening workout at the weekend, because it closes at 18:00 on Saturday and Sunday') = '73c786003c52289eb6956ecd0a618651'),
  (112, 'genius-bistro', 'why_its_here', (select count(*)::int from venues where slug = 'genius-bistro' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '13eb178208b2e4b40b75bd7a9d11f39b'), md5('Among rice fields north of central Canggu, Genius Bistro cooks French, Mediterranean and steakhouse food on Jl. Sempol. About 50 seats split between indoors and al fresco. The kitchen leans French: duck served at the table, braised lamb shank, duck a l''orange. Book through Chope.') = '29febb691bdef39df129ed08e4aee3b4'),
  (113, 'genius-bistro', 'best_for', (select count(*)::int from venues where slug = 'genius-bistro' and status = 'active' and publication_status = 'published' and md5(best_for) = '1650a2bd47c2b41d256c990af85924ac'), md5('A sit-down meal of French cooking or steak among rice fields north of central Canggu') = '62dacca032fbf906cd191fc4218f4905'),
  (114, 'glo-day-spa-salon-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'glo-day-spa-salon-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c7bc1221241797035dca5c0a0962437f'), md5('One of five Bali branches of Glo Salon & Beauty, which used to trade as Glo Day Spa & Salon. It sits at Jl. Subak Sari 90, opposite Popular supermarket. It covers hair, facials, nails, waxing, threading, lash and brow, spray tanning and makeup.') = '164276bde0af778693ec306a41e4e84d'),
  (115, 'glo-day-spa-salon-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'glo-day-spa-salon-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c090f09236792b6841ef0d2b7794c4b9'), md5('Hair, nails, waxing and facials in one Canggu salon, open 10am to 8pm') = '0dd4589832fd22a9b6059dd5f6786df5'),
  (116, 'glo-day-spa-salon-canggu-canggu', 'not_for', (select count(*)::int from venues where slug = 'glo-day-spa-salon-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e73a8a910d18202918c5f89adba56245'), md5('An early-morning or late-evening slot: it opens at 10am and closes at 8pm') = '28cf6831cf42090b1b9cbab0e0717a9e'),
  (117, 'goldust-beauty-facials-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'goldust-beauty-facials-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e546aff2f118ff1790b88bfac820d543'), md5('The facial and beauty side of Goldust, a Canggu day spa. Its treatments are results-focused, the Express Lifting Facial among them.') = 'c21498db1c54d2ea6a204d202fe740cb'),
  (118, 'goldust-beauty-facials-canggu', 'best_for', (select count(*)::int from venues where slug = 'goldust-beauty-facials-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '213859874058bd9ab6947479ea439c74'), md5('A results-focused facial or skin treatment rather than a quick massage') = 'c5f6b44d4febdd8e279c169e21958999'),
  (119, 'goldust-spa-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'goldust-spa-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'eecfe8f1be3bf28f283e089857b59868'), md5('Goldust Spa is a day spa on Gg. Nyepi, off Jl. Pantai Batu Bolong. Under one roof are massage suites, a poolside lounge, a nail lounge and a couple''s room. The list runs from 30-minute poolside massages to 24k Gold facials and two-and-a-half-hour couple''s packages.') = '60b5f6f7880b20042cec69281ee33c86'),
  (120, 'goldust-spa-canggu', 'best_for', (select count(*)::int from venues where slug = 'goldust-spa-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c326f94660878d6d276452ee6f82d4f3'), md5('Therapeutic bodywork, from sports and lymphatic drainage to Madero body sculpting, rather than a basic massage') = '6a11e9ef06f8cdf69d96cb539d9bb653'),
  (121, 'gravity-stretching-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'gravity-stretching-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8abd593c271fc5c8d26a45284a418433'), md5('A stretching studio built on suspended ropes: the exercises are done in relaxation rather than tension, so gravity takes the load off the muscles. The Bali operation has studios in Canggu and Ubud, with group classes, private Gravity Therapy sessions and a children''s class.') = '68448c740c1cf798e9c1d7b0531cd783'),
  (122, 'gravity-stretching-canggu', 'not_for', (select count(*)::int from venues where slug = 'gravity-stretching-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '5c3df79597fbaccc8e57d03f7941f064'), md5('An unbooked visit: classes go through the studio app or WhatsApp') = '90ff1e262f8d8f8fd56859cfdf216820'),
  (123, 'green-spot-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'green-spot-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5208d219595a9ed4144b7314fccb9db5'), md5('Green Spot, the cafe of Ecosfera Hotel at Echo Beach, serves an all-day international menu of breakfasts, burgers, bowls and grills. Its menu page lists breakfast from 35K and lunch mains up to 115K, plus weekly deals like a Wednesday burger-and-drink and Sunday two-for-one smoothies.') = '105ba54eee35773bb9d85dc8bf17eabe'),
  (124, 'green-spot-cafe', 'best_for', (select count(*)::int from venues where slug = 'green-spot-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '09d136f446c92c328fd8fcf6daadafae'), md5('A big, low-priced breakfast or burger at Echo Beach, with the kitchen open until 11pm') = '3feba4229c9d1e995deb1f20976543b1'),
  (125, 'guan-yin-yoga-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'guan-yin-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '08a749d5c9fc457da78d762d500f7af3'), md5('Guan Yin has its yoga shala on the upper floor of Hotel Tugu Bali, on Jl. Pantai Batu Bolong at Canggu Beach. The published timetable runs Vinyasa, Yin, Hatha Flow, Ashtanga, Kundalini, Qigong, gentle Pilates and guided meditation. Non-guests can walk in.') = 'fff726b0fc00fcb0c072583bd00a7b32'),
  (126, 'guan-yin-yoga-canggu', 'best_for', (select count(*)::int from venues where slug = 'guan-yin-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b0d368808fd93ac71427ab4cfe434d98'), md5('A small drop-in class upstairs at Hotel Tugu, walk-ins welcome') = '6e769edabf668549c038884ea9ad102a'),
  (127, 'guan-yin-yoga-canggu', 'not_for', (select count(*)::int from venues where slug = 'guan-yin-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c32107879831f1e1454fdee389d8e5fa'), md5('Dropping in at any hour, because classes run only on the weekly timetable') = 'd54835f3d2359635303d637d06f9ce88'),
  (128, 'home-by-chef-wayan', 'why_its_here', (select count(*)::int from venues where slug = 'home-by-chef-wayan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5bbb70d0e816efe146fca20e8a7def97'), md5('Near the beach on Jl. Pantai Pererenan, Chef Wayan Kresna Yasa runs HOME, a modern Balinese restaurant. The kitchen reworks family and island recipes with contemporary technique. Vegan dishes are marked on every course, next to sate, seafood and traditional mains.') = '05f1a185fd9969bdd82e4076d9206d49'),
  (129, 'home-by-chef-wayan', 'best_for', (select count(*)::int from venues where slug = 'home-by-chef-wayan' and status = 'active' and publication_status = 'published' and md5(best_for) = '35cee210f696b5bcc7a67e23bcb8445f'), md5('Tables that mix meat, seafood and vegan eaters over a considered Balinese dinner') = '8798719f7a71203784cddd106348bc2a'),
  (130, 'home-by-chef-wayan', 'not_for', (select count(*)::int from venues where slug = 'home-by-chef-wayan' and status = 'active' and publication_status = 'published' and md5(not_for) = 'dbbb4bc2a72411da23f80a816f43caa3'), md5('A walk-in table. The restaurant asks you to book ahead') = 'cb071a9fd5f65af3e980e483b2e80f85'),
  (131, 'indigo', 'why_its_here', (select count(*)::int from venues where slug = 'indigo' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '97fca5dcc64b0bdbdcb3a268780c8412'), md5('Indigo has served Japanese food in Berawa since 2017 under Kyoto-trained chef Morita Shigehiko. There is a sushi and sashimi selection, and yakimono cooked over charcoal. The room is small and deliberately plain, with shoji-style doors, timeworn teak and indigo denim cushions.') = 'eb338f6f032f9d0e7331a3e093073778'),
  (132, 'indigo', 'best_for', (select count(*)::int from venues where slug = 'indigo' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ff82a5e713d13980421153789ede9566'), md5('A quiet meal of sushi and charcoal-grilled yakimono in a small Berawa room') = 'bb51a0db8f1db3ef774d165198a81938'),
  (133, 'isla-by-earth-island', 'why_its_here', (select count(*)::int from venues where slug = 'isla-by-earth-island' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f723b9c202fa02abe185653bc226d8c1'), md5('ISLA, the all-day cafe at Earth Island''s surf shop, sits at Jl. Subak Canggu No.77 on the Canggu shortcut. The menu goes from breakfast and coffee through seafood snacks and grilled mains to cocktails. The site calls it a space for events, music, art and film.') = 'd4ef2babe45c92809babe4082b7401d1'),
  (134, 'isla-by-earth-island', 'best_for', (select count(*)::int from venues where slug = 'isla-by-earth-island' and status = 'active' and publication_status = 'published' and md5(best_for) = '8deef2f33ce956f726cbad418daed128'), md5('Breakfast or seafood snacks after a surf, at the Earth Island surf shop') = '7c65cf02ac8b205f6f4f07ab8c5e66ea'),
  (135, 'isla-by-earth-island', 'not_for', (select count(*)::int from venues where slug = 'isla-by-earth-island' and status = 'active' and publication_status = 'published' and md5(not_for) = '8913e78fd40f6e30fa688b00967c8898'), md5('Dinner from Sunday to Thursday, because it closes at 7pm; only Friday and Saturday run to 9pm') = '4ee4e44ffa44e40437bfc88853d0909f'),
  (136, 'jet-black-ginger-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'jet-black-ginger-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '41a47bc39de1e9b3dc8daf641ede1689'), md5('A cut or colour by stylists used to international hair') = 'f3eca3f8f9c45b01d12a9dc36b8bc82b'),
  (137, 'ju-bali', 'why_its_here', (select count(*)::int from venues where slug = 'ju-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5d840ce6ffb38544ec96261e9e18b8ca'), md5('Ju Bali is a casual Umalas restaurant with a jacuzzi club. International comfort food with a Balinese turn: pasta, burgers and wood-fired pizza. Vegetarian and vegan plates include tandoori cauliflower and mushroom tagliatelle. Its 200 seats come with a kids menu and parking for cars and scooters.') = 'c413f144012afe6a718ab8d8b094f9f0'),
  (138, 'ju-bali', 'not_for', (select count(*)::int from venues where slug = 'ju-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = 'bd4bd1059b62f9fa7b991e5edf35b8c9'), md5('A quiet dinner for two, because it is a 200-seat family venue') = 'ed6a06bb053f00eb8005c31c875aa9bc'),
  (139, 'jungle-padel-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'jungle-padel-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e5f09aec03f1f2a05fa47e68eb5d6e28'), md5('Jungle Padel runs padel courts in Canggu, open early until late for court hire and social games.') = '1aee43ca78e52ce46addee2bdae16127'),
  (140, 'jungle-padel-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'jungle-padel-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ba2f802a578f854c7df31fcb43afb87e'), md5('Groups and couples after a fun, active session on court instead of a gym') = 'a1d01d3b5634d78ba898e4044e283619'),
  (141, 'jungle-padel-canggu-shortcut', 'why_its_here', (select count(*)::int from venues where slug = 'jungle-padel-canggu-shortcut' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'bb9ea100016bfb003e78a6935b52393a'), md5(U&'A padel club on the Canggu shortcut, with panoramic glass-walled courts among tropical greenery. Courts are booked by the hour on the Jungle Padel app. Racket hire, coaching, a pro shop, changing rooms and an on-site caf\00E9 are all there.') = 'f27d0184d96129fba5df09df69a05eb5'),
  (142, 'jungle-padel-canggu-shortcut', 'best_for', (select count(*)::int from venues where slug = 'jungle-padel-canggu-shortcut' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e62c24f09f9de43ba1ae16f93c2ce04c'), md5('A game between beach sessions: book a court for four, or come for a lesson, with racket hire on site') = 'c307ccf9ef57d44ca65943dbdec5e01e'),
  (143, 'jungle-padel-canggu-shortcut', 'not_for', (select count(*)::int from venues where slug = 'jungle-padel-canggu-shortcut' and status = 'active' and publication_status = 'published' and md5(not_for) = '90b47e608b523b82b1a91e68b7f1b71c'), md5('Total downtime or a spa-style wellness stop: this is a sports club, and peak-time courts need booking') = 'abc13a9b0b1fb6e12d9bddda7bccac62'),
  (144, 'kecambah-restaurant-at-lalasa-villas', 'why_its_here', (select count(*)::int from venues where slug = 'kecambah-restaurant-at-lalasa-villas' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3e2dcb04cf8f353a27a8e0c66a20e27d'), md5('Lalasa Villas on Pantai Berawa has Kecambah as its street-front restaurant, a casual room open from breakfast until late. The cooking leans Indonesian, with Western dishes too. There is a Balinese rijsttafel evening, and afternoon tea is booked ahead.') = '6f354de1b4044119ea92f9f6ec6817e0'),
  (145, 'kecambah-restaurant-at-lalasa-villas', 'best_for', (select count(*)::int from venues where slug = 'kecambah-restaurant-at-lalasa-villas' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a8e54f8d52f0e17d837b1de693a6d3c5'), md5('Breakfast through to a late dinner at Lalasa Villas, or the Balinese rijsttafel evening') = '803a0ac27c3e637b73a64ad2953542fa'),
  (146, 'kopiten', 'best_for', (select count(*)::int from venues where slug = 'kopiten' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e07f74afe278f32fd53501a57b1a7d90'), md5('Remote workers and long-stay visitors after a quiet, low-key coffee away from the busier Canggu cafes') = '67039f4214d8486b11856c112cc8c23d'),
  (147, 'la-brisa-bali', 'why_its_here', (select count(*)::int from venues where slug = 'la-brisa-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '362f7ee9a2273c5a72f76ea1f7feff99'), md5('La Brisa is a rustic beach club on Echo Beach, hand-built from wood salvaged from old Indonesian fishing boats. It has a saltwater pool, a raw and oyster bar and wood-fired Mediterranean food. Expect a driftwood look and long, open sunset views over the surf break.') = '2b73538fdcb87d9698036395bae82cc4'),
  (148, 'la-brisa-bali', 'best_for', (select count(*)::int from venues where slug = 'la-brisa-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '3d7f94bdfcbe8aba5dc8573b67368fd7'), md5('Sunset drinks and a beach day with friends, or a shared meal by the water') = 'b076607bfa23c63a94bf0fbd065f127c'),
  (149, 'la-brisa-bali', 'not_for', (select count(*)::int from venues where slug = 'la-brisa-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = 'd67f3a058d85542cf1831e6a5aab7d4d'), md5('A low-spend sunset on a daybed: after 4pm, daybeds and cabanas carry a 1M-3.5M++ minimum spend') = 'c52d22168e31fe8747097145db3c135e'),
  (150, 'loop-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'loop-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1d03290a7954622163043b4c674448d5'), md5('Eggs, salmon, chicken, cottage cheese, Greek yoghurt, oats and sourdough make up the menu at LOOP, a high-protein breakfast cafe in Pererenan. Six protein shakes are made for after training. Specialty coffee and smoothie bowls share the menu with wraps and vegan options.') = '4874e61be4d20cf9dc13ffe564e0eb35'),
  (151, 'loop-cafe', 'not_for', (select count(*)::int from venues where slug = 'loop-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = '10c08b9ff6cc008a6b317dee800c00d5'), md5('Dinner, since the kitchen closes at 18:00') = '364f2258740183a5f161e9053ee07917'),
  (152, 'lowcal-cheatery-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'lowcal-cheatery-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '62130113ad39bdc0e9ecf2dfdc3308cd'), md5('LowCal, on Jalan Pantai Batu Bolong, builds a low-calorie menu that also covers paleolithic and ketogenic eating. It trains and employs deaf team members across kitchen, bar and service roles. Dinner choices include chicken, pork, fish and vegetarian dishes, with low-carb sides.') = '0fa54f0297f1bfc8fad295987b9b1b71'),
  (153, 'lowcal-cheatery-and-bar', 'best_for', (select count(*)::int from venues where slug = 'lowcal-cheatery-and-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '9f4301b721a35466bc7f57cc2958c5ec'), md5('A health-led meal with low-carb choices, served by an inclusive team') = '1a8ad3e34c670a9c618daa2826929b7d'),
  (154, 'lowcal-cheatery-and-bar', 'not_for', (select count(*)::int from venues where slug = 'lowcal-cheatery-and-bar' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c6ea437597817352dac5066a343a46e8'), md5('A traditional Balinese warung meal, because the menu is built around low-calorie, paleolithic and ketogenic food') = 'aeddb04479b15a0dcf38a0d97cfe9f92'),
  (155, 'lulu-bistrot', 'why_its_here', (select count(*)::int from venues where slug = 'lulu-bistrot' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '65b45c5b5e70aa099a1a61550540d1d0'), md5('On Jl. Pantai Batu Bolong, Lulu Bistrot cooks classic French bistro dishes with local, seasonal ingredients. The room and bar take their cue from the grand cafes. It opens in the evenings, with an early happy hour.') = '189ea6b92b4c8fa4a692a5b94bd76efd'),
  (156, 'lulu-bistrot', 'best_for', (select count(*)::int from venues where slug = 'lulu-bistrot' and status = 'active' and publication_status = 'published' and md5(best_for) = '5b06b9791abcad62cd0e8f1d07f8b4cf'), md5('Couples and small groups after an unhurried French dinner and drinks') = '882d986b48f2ddac19fd5149000b977a'),
  (157, 'lulu-bistrot', 'not_for', (select count(*)::int from venues where slug = 'lulu-bistrot' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a91dab908a3ae8e5add82a805789f8e4'), md5('A quick warung stop or a budget meal: Lulu serves unhurried French bistro dinners') = 'b24416767b5ed78cbe8f93a203ee570a'),
  (158, 'luma', 'why_its_here', (select count(*)::int from venues where slug = 'luma' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '11eb8d5a534084981b921bb115ca10fa'), md5('An intimate, 30-seat open-air spot on Batu Bolong, Luma cooks rustic Mediterranean small plates. The chefs are Cameron Emirali, of 10 Greek Street in London, and Kieran Morland, of Merah Putih and Sangsaka. Beer and cocktails are on tap; vinyl DJs play at weekends.') = '64e679aea5ef4d65ff873f8aae1927db'),
  (159, 'luma', 'best_for', (select count(*)::int from venues where slug = 'luma' and status = 'active' and publication_status = 'published' and md5(best_for) = '7522ac3d87b6a98c0d896ff9d58f8f99'), md5('Spanish- and Italian-style grazing over golden-hour drinks, on a date or as a lively pre-dinner stop that becomes the evening') = '1ef5012c04bced123c6e48cb0db41217'),
  (160, 'lyma-beach', 'why_its_here', (select count(*)::int from venues where slug = 'lyma-beach' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c72c9ee54df309c1ad5d99492f60420a'), md5('Lyma Beach is a beachfront bar and restaurant on Pantai Lima, where the river meets the ocean. Expect sunset views, cocktails and live entertainment through the week.') = 'edd78bde2ee8165d19b1b931a3ed7eb3'),
  (161, 'lyma-beach', 'best_for', (select count(*)::int from venues where slug = 'lyma-beach' and status = 'active' and publication_status = 'published' and md5(best_for) = '9284a7fb91e571e69de0bbeedadf6d7d'), md5('Sunset drinks with a group, or a beachfront meal to live music') = 'f307b45e99e61a03b1b3e792fa8a805c'),
  (162, 'lyma-beach', 'not_for', (select count(*)::int from venues where slug = 'lyma-beach' and status = 'active' and publication_status = 'published' and md5(not_for) = '15df62be9fc76b9084e8f3f7d3755101'), md5('A quiet work session or an intimate fine-dining evening, because there''s live entertainment through the week') = '44d3c00439c91319a241ac44118008af'),
  (163, 'manhattan-cocktail-hookah-kitchen', 'why_its_here', (select count(*)::int from venues where slug = 'manhattan-cocktail-hookah-kitchen' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b7a42ca5bb0b60a4b6091efccc276d42'), md5('Manhattan puts shisha service and a kitchen alongside a cocktail bar on Jl. Pantai Batu Bolong. It publishes no website beyond a link page, and its menu is not readable online. We can confirm the format, the address and WhatsApp booking.') = '253f3c0ca8bd75cbd21d291bd17de27b'),
  (164, 'manhattan-cocktail-hookah-kitchen', 'best_for', (select count(*)::int from venues where slug = 'manhattan-cocktail-hookah-kitchen' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ecea1c8675f9503c51dfd61c6cefea2e'), md5('Cocktails and shisha with a kitchen attached, on Batu Bolong') = 'e54d11ee45582cd9080adf0ed0d75bac'),
  (165, 'mason', 'why_its_here', (select count(*)::int from venues where slug = 'mason' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '551af63788b4639ec749c058f2ad0d39'), md5('Trading as MASONRY., Mason runs a moody, minimalist grill on Batu Bolong. The cooking is wood-fired and leans Mediterranean, the charcuterie is made in-house, and there is a wine and cocktail list.') = '040bef19ae34ffd76227c4390509d8f6'),
  (166, 'mason', 'best_for', (select count(*)::int from venues where slug = 'mason' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd21b95afb978de5b37c139f3aa41d6b0'), md5('A sit-down meal of wood-fired grill, charcuterie and wine, from midday to late') = '1348673b57d0791d75e27a3095f0cf9d'),
  (167, 'mason', 'not_for', (select count(*)::int from venues where slug = 'mason' and status = 'active' and publication_status = 'published' and md5(not_for) = 'b338bd5fb4f4381b99579dbb09876fda'), md5('Lunch in the Chop House room, which runs dinner only, Tuesday to Saturday') = '6186e33dad74d13426976062a35eda86'),
  (168, 'mia-asian-modern-inspired-restaurant-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'mia-asian-modern-inspired-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '68f1a2cb9f43bcc848dd21d8c690bac4'), md5('Off Jl. Raya Semat, MiA is a modern Asian restaurant and bar built around sharing. Sushi rolls, raw plates, curries, wok and grill dishes make up the menu, and it runs into the early hours at weekends.') = '5ca4ef45cbc06b69c80a7c57bb3e6d06'),
  (169, 'mia-asian-modern-inspired-restaurant-and-bar', 'best_for', (select count(*)::int from venues where slug = 'mia-asian-modern-inspired-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '7569873dff3626d57cb9fedee77db681'), md5('Dinner into the late hours over modern Asian sharing plates and sushi') = '8338a90c8cbc7b797a410d15935cb2bb'),
