  (173, 'milk-and-madu-berawa', 'why_its_here', (select count(*)::int from venues where slug = 'milk-and-madu-berawa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '58ddeaf6f45794040939b2631511b8bf'), md5('The Berawa flagship of Milk & Madu, an all-day Canggu cafe brand. It does hearty brunch, lava-stone pizzas and family-friendly dinners.') = '9c06de9ef50f32554dd5c4a6a23e3f11'),
