  (176, 'milu-by-nook', 'why_its_here', (select count(*)::int from venues where slug = 'milu-by-nook' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '26c46601ef7f6a16361608b7a98ea203'), md5('Milu by Nook, a restaurant on Jl. Pantai Berawa, has a garden looking over a small rice paddy. It serves Balinese-Western dishes and coffee from morning until night.') = '425061c69c1e391e16a877af761ed4cf'),
