  (183, 'mosto-berawa', 'best_for', (select count(*)::int from venues where slug = 'mosto-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = '908b4246eb522b475e1efe78ba5c5e69'), md5('A date, an intimate dinner over natural wine, or a small group of wine lovers') = '501202fb28a0e48cefe44f5a5998368b'),
