  (198, 'nirvana-strength-tibubeneng', 'best_for', (select count(*)::int from venues where slug = 'nirvana-strength-tibubeneng' and status = 'active' and publication_status = 'published' and md5(best_for) = 'baf4f171676a0102aa970d2c1e59f569'), md5('A day pass covering 20-plus classes and the recovery spa') = '265e42a3560af85365cb995e44d950c9'),
