  (200, 'nude-berawa', 'best_for', (select count(*)::int from venues where slug = 'nude-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = '0910b65a2188b78456dc9f29ac6fb5ff'), md5('Digital nomads and families after a healthy brunch or a casual all-day meal') = 'de85053d26b705087062a487fd5691f2'),
