  (205, 'only-nails-pererenan', 'best_for', (select count(*)::int from venues where slug = 'only-nails-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = '0163af94551486e561593471ebd6dcf0'), md5('A precise Russian manicure or long-lasting gel, or a quick 4-hands mani-pedi') = '2c6afcb90f4db4cda6408f69e98cef2d'),
  (206, 'paed-thai-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'paed-thai-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '70d213e7a8d9c24e2fa2a87f629a1505'), md5('Part of the Wonderspace group, Paed Thai cooks Thai food on Jl. Canggu Padang Linjong. The menu has tom yum goong, pad thai, green curry and mango sticky rice. Indoor and outdoor tables face rice fields.') = '5b6b3f084e87d517ebb2bcd13c9c5cec'),
  (207, 'pizza-fabbrica', 'why_its_here', (select count(*)::int from venues where slug = 'pizza-fabbrica' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'dfad6bdce053a0bd4f23355b52c82eee'), md5('Pizza Fabbrica is a Neapolitan pizzeria on Jl. Batu Mejan, with a second branch in Umalas. The pizzas are wood-fired, thin and light, the pasta is fresh, and the room is industrial in style.') = '319047ccf847baf5db5e45fe65d46095'),
  (208, 'pizza-fabbrica', 'best_for', (select count(*)::int from venues where slug = 'pizza-fabbrica' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a378dc23b8c640f4ed8d5ed152e3bfd2'), md5('A casual pizza dinner with friends, family or a group sharing') = 'c01bd1041a77efd195b2f822e399358a'),
  (209, 'poule-de-luxe-bali', 'why_its_here', (select count(*)::int from venues where slug = 'poule-de-luxe-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fe98d41029666809927a175996924d83'), md5('Poule de Luxe makes cream puffs, macarons, tarts and viennoiserie in its French patisserie and bakery on Jl. Batu Belig. You can eat in or take away. It also supplies desserts to villas and restaurants, and for parties.') = 'b00eddd5d436d8932836e127c1ac0bd9'),
  (210, 'poule-de-luxe-bali', 'best_for', (select count(*)::int from venues where slug = 'poule-de-luxe-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '77a58eef7758ccb1c135be405a0c3f2f'), md5('A pastry with coffee, a grab-and-go breakfast, or a letter cake or gift for a celebration') = '3302fe9206c5a520cfad21e11d3bde86'),
  (211, 'poule-de-luxe-bali', 'not_for', (select count(*)::int from venues where slug = 'poule-de-luxe-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '48a49c36dfc7db38444ac3e6bf8017fe'), md5('A full sit-down meal or a savoury dinner, since it bakes pastries and cakes') = 'ffaf2fd09243c6ce9495a41460049101'),
  (212, 'revolver-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'revolver-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '75d72f429d93aa26401e8411a16369fc'), md5('Revolver, a Bali coffee brand founded in 2012, roasts its own beans; this is its all-day cafe on Jl. Nelayan in Canggu. Espresso and full brunch run by day, heavier plates in the evening, and it turns bar-ish after dark.') = 'd350354962267c72e127a3549b195c05'),
  (213, 'revolver-canggu', 'best_for', (select count(*)::int from venues where slug = 'revolver-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '2d518e710873f1aa0bb583dc4506770d'), md5('Coffee-led brunch after a surf, a morning on the laptop, or an easy all-day sit-down') = '4cf8d3be4cfe775ebcc8a65289c2437c'),
  (214, 'revolver-canggu', 'not_for', (select count(*)::int from venues where slug = 'revolver-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '33c14ca7e03a29c9fadaf6b4000073e7'), md5('A calm evening meal, since it turns bar-ish after dark') = '453c92ce10146defd831817ae9b8ce29'),
  (215, 'rise-and-shine-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'rise-and-shine-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5e14d3eaa3a4f28a2e1d77c43ad980bd'), md5('Open since 2017 on Jl. Padang Linjong, Rise and Shine is a colourful all-day breakfast and lunch cafe. It serves fresh, health-conscious comfort food with coffee and juices, all in the open air.') = '28a13591bdb6ca468482f34d9636082f'),
  (216, 'rise-and-shine-cafe', 'best_for', (select count(*)::int from venues where slug = 'rise-and-shine-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd0b76f39350c525224cf97c73f850bd7'), md5('A healthy breakfast or brunch after the beach, for solo travellers, couples and small groups') = '460783a224e985fc8d06fc9d502f98ff'),
  (217, 'rise-and-shine-cafe', 'not_for', (select count(*)::int from venues where slug = 'rise-and-shine-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = 'f675c4ff069dbe7f9a4df683c8780fb3'), md5('Evening dinner or drinks, because it serves breakfast and lunch by day') = '4ae2d4161fc8064fb85384ee7daf3a7d'),
  (218, 'rite-bali', 'why_its_here', (select count(*)::int from venues where slug = 'rite-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'facb4483f63439abfcc631c66ec3ccc0'), md5(U&'RITE Bali, a wellness club on Jl. Pantai Pererenan, has a gym, yoga classes and a recovery zone. Recovery pairs a sauna and steam room with a jacuzzi and a 7-9\00B0C cold plunge. A 500k day pass bundles recovery with gym access.') = '6299d6d7ee4913eb3a7db8c950e8a3cc'),
  (219, 'rite-bali', 'best_for', (select count(*)::int from venues where slug = 'rite-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd72ec11ae10d8b4b64cc4bc68e41b53b'), md5('Athletes and active travellers after training, yoga and contrast recovery in one Pererenan spot') = '615cc8325c77adfd205b7e278a8ded36'),
  (220, 'rite-bali', 'not_for', (select count(*)::int from venues where slug = 'rite-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '95b9f9b95d04fa57c5804ef7d6271026'), md5('A traditional pampering spa. Recovery here is sauna, steam room, jacuzzi and cold plunge') = '0c254f3f7c9e7023629260ccdcdc16c2'),
  (221, 'rite-bali-recovery-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'rite-bali-recovery-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '94e6ad5b5f6a541d4cce9ee67b0cb965'), md5('The recovery-and-spa side of RITE Bali in Pererenan. Sauna, ice bath and bodywork come bundled with gym access on a 500k day pass.') = '5c0a16e40190026ce09e8639aa5505b3'),
  (222, 'rite-bali-recovery-canggu', 'best_for', (select count(*)::int from venues where slug = 'rite-bali-recovery-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'bd809e4ba8a9dd93c68df87966492228'), md5('Fitness travellers pairing training with contrast recovery on one day pass') = '22e75c4c0f57e37e53318a1c9038179d'),
  (223, 'rite-bali-yoga-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'rite-bali-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5b91e55d35eede24c03c4caaf3033a67'), md5('The yoga strand of RITE Bali in Pererenan, with classes alongside the club''s gym and recovery facilities.') = '145586e958bd3a14eed999f97cb27950'),
  (224, 'rite-bali-yoga-canggu', 'best_for', (select count(*)::int from venues where slug = 'rite-bali-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd3604327bfef84090d6d377f1f588f4c'), md5('Members and visitors after yoga bundled with training and recovery') = '16284c639365ed7c500553db5c3ac053'),
  (225, 'riviera-bistro-berawa', 'why_its_here', (select count(*)::int from venues where slug = 'riviera-bistro-berawa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6a5ef91e1a622776db33dfd48a42cfa7'), md5('Riviera Bistro, open since 2020, is a modern Mediterranean bistro and wine bar in Berawa with whitewashed arches. The wine list is extensive, Aperitivo hour runs daily, and Saturday is DJ night. It opens from late morning until late.') = '0ad6f6197c249f91a2720c4783cd416e'),
  (226, 'riviera-bistro-berawa', 'best_for', (select count(*)::int from venues where slug = 'riviera-bistro-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c00d7567a9b18316981b64c44ba602d3'), md5('A date night, aperitivo, or a lively evening of dinner and drinks') = 'bf6c81892388957de7cf664d56ac9f00'),
  (227, 'riviera-bistro-berawa', 'not_for', (select count(*)::int from venues where slug = 'riviera-bistro-berawa' and status = 'active' and publication_status = 'published' and md5(not_for) = '35fdf6c30b072227311511a389247072'), md5('A quiet or budget spot. Evenings here are lively, with a Saturday DJ night') = '37dc629eb0e3d37858257a465b69cba6'),
  (228, 'riviera-cafe-cemagi', 'why_its_here', (select count(*)::int from venues where slug = 'riviera-cafe-cemagi' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd3ec6082fa013592f5d180f6e38644d5'), md5('Riviera Group''s garden cafe in quiet Cemagi leans Mediterranean-Italian, with cozy interiors and greenery. Live acoustic music plays on Saturday evenings.') = 'dc4bc072f3bde3ddeec940b166dbf540'),
  (229, 'riviera-cafe-cemagi', 'best_for', (select count(*)::int from venues where slug = 'riviera-cafe-cemagi' and status = 'active' and publication_status = 'published' and md5(best_for) = '53e8d04cabefa87c3d0cbe6497f314d5'), md5('Calm breakfasts, lunches or evening meals away from the Canggu crowds, or a low-key night for a couple') = 'ea60c4119a15db5ada9ec46bd21b1c4b'),
  (230, 'riviera-cafe-cemagi', 'not_for', (select count(*)::int from venues where slug = 'riviera-cafe-cemagi' and status = 'active' and publication_status = 'published' and md5(not_for) = '2669c850f9f6c471b2fe183eb5a3ef94'), md5('Beachfront views or a high-energy party scene: the cafe sits in a garden in quiet Cemagi') = 'f84d6f04abe9c5f552aad3ab442cd69f'),
  (231, 'riviera-trattoria-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'riviera-trattoria-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0e25d6b694cde963e13f6f3fc8f3c83a'), md5('The Riviera Group''s Italian trattoria in Pererenan does hand-rolled pastas and Neapolitan pizzas, with an extensive wine and cocktail list. The room is cozy and lively.') = 'bf580afa6442b875372b8e957ef177ae'),
  (232, 'riviera-trattoria-pererenan', 'best_for', (select count(*)::int from venues where slug = 'riviera-trattoria-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = '07fdd52a12de9f81d1243b0afa75eef9'), md5('A date night, a group dinner over shared plates and wine, or a lively, casual evening') = '2cbf095734752ff66ef5d43df7a8c04f'),
  (233, 'riviera-trattoria-pererenan', 'not_for', (select count(*)::int from venues where slug = 'riviera-trattoria-pererenan' and status = 'active' and publication_status = 'published' and md5(not_for) = '1774c38cb403e58a144870287a6c8727'), md5('A quiet daytime work session or a beachfront table, because the trattoria room is cozy and lively') = '7049b69a3827ec64e285c490be71d6c6'),
  (234, 'rize-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'rize-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '81864d6ac9fe67fbb83a78c1add7c5b5'), md5('Spices are ground daily at Rize, a Pererenan cafe serving contemporary Indian home cooking rooted in family recipes. Brunch classics, craft cocktails and house chai fill out the menu.') = '54e03d63f75cb090c78aaca803311466'),
  (235, 'rize-cafe', 'best_for', (select count(*)::int from venues where slug = 'rize-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '5fab0526973163114e5539574d8c42eb'), md5('Spice lovers and small groups sharing Indian dishes, a distinctive brunch, or cocktails and chai') = '3d912dabbb4310d46fb773836e5ef3f8'),
  (236, 'rize-cafe', 'not_for', (select count(*)::int from venues where slug = 'rize-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = 'b877fe7487b4c45c89904b1380917ca8'), md5('A beach-club or sunset-view scene, because the focus is Indian home cooking') = '0c2b9c22d0c7797a6599357a15b6da21'),
  (237, 'ruko-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'ruko-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '89c5330610f4caa6af826073f72242fc'), md5('About 300m from Berawa beach, Ruko is an Australian-style neighbourhood cafe for breakfast and brunch. The food is healthy and locally sourced, 40-50% of the produce is local and organic, and the coffee is its own Indonesian blend.') = 'f7beccabcf165dcf7080d7a653ee5efa'),
  (238, 'ruko-cafe', 'best_for', (select count(*)::int from venues where slug = 'ruko-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '80db2ec7c10ca69dd1293f9cc4d8070b'), md5('Families, couples or solo travellers after a fresh, organic-leaning breakfast or brunch and coffee after the beach') = '5b0f581c213746ef60a84e62fc9c221b'),
  (239, 'ruko-cafe', 'not_for', (select count(*)::int from venues where slug = 'ruko-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = '109969b9c6555774280103253e809c54'), md5('An evening out or dinner: it is a daytime cafe') = '42ea53ddade701d43e07c409d73de0d2'),
  (240, 'sa-mesa-canggu-experience-dining', 'why_its_here', (select count(*)::int from venues where slug = 'sa-mesa-canggu-experience-dining' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd980e6552aae7f7ae53a1e4ccbacc64f'), md5('One long communal table is the centre of Sa''Mesa, an Italian restaurant in Canggu open since early 2021. There is no menu: guests share a set procession of roughly 14-18 dishes that changes daily. Plates like tuna crudo, grilled octopus and house fettuccine go down the middle.') = '6f18339026fa70ee7f50638665eaa512'),
  (241, 'sa-mesa-canggu-experience-dining', 'best_for', (select count(*)::int from venues where slug = 'sa-mesa-canggu-experience-dining' and status = 'active' and publication_status = 'published' and md5(best_for) = '2b93e98a74c1529c1fbefd75f66ff7eb'), md5('Groups or solo diners happy to share one table with strangers over a set Italian dinner') = 'b30cd229eb576b3af894b10e9b77052a'),
  (242, 'sama-sama-prime', 'why_its_here', (select count(*)::int from venues where slug = 'sama-sama-prime' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '68ac2d2cb80917a163c88c058bd8c3fb'), md5('Sama Sama Prime, from the Sama Sama group, combines a steakhouse and a sushi bar on Jl. Raya Semat. Its own site calls it a steakhouse sushi bar on the homepage and a modern premium Japanese restaurant on the about page. We have not settled which.') = 'bd99942c17e53cfbbcb8f355fbb428c5'),
  (243, 'sama-sama-prime', 'best_for', (select count(*)::int from venues where slug = 'sama-sama-prime' and status = 'active' and publication_status = 'published' and md5(best_for) = 'eaa81c4514b8b5dc1c5ba8c186f8b01d'), md5('Steak and sushi under one roof, on Jl. Raya Semat in Canggu') = '6bc6b40437314b444e98faf9d4cc5175'),
  (244, 'samadi-bali', 'why_its_here', (select count(*)::int from venues where slug = 'samadi-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '062cd51ff5337eaa688ced058262d406'), md5('Samadi is a yoga and wellness hub on Jl. Padang Linjong, in the Batu Bolong part of Canggu. Its organic vegetarian cafe is certified by the Slow Food movement and serves superfood bowls and traditional Indian dishes.') = 'bc29f4bb12407800e2054bedb190727c'),
  (245, 'samadi-bali', 'best_for', (select count(*)::int from venues where slug = 'samadi-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '2c119ac236d35c108d686251b15d6c7a'), md5('A calm, plant-based meal on either side of a yoga class') = '7ecb0f1ec829915a546c56e545151c87'),
  (246, 'samadi-bali', 'not_for', (select count(*)::int from venues where slug = 'samadi-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '4e7557f274c207c58df277ef97462cbf'), md5('Meat, alcohol or a high-energy social scene: the cafe is vegetarian and the hub is built around yoga') = '7a4d0b66de76d40f7b51afe9d7a93a25'),
  (247, 'samesa-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'samesa-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e091477cc4724922e650cef3efb54f3c'), md5('A communal Italian dinner where everyone shares one long table. The multi-course set menu is family-style, inspired by an Italian grandmother''s table. There is one seating, dinner only, and you book ahead.') = 'c4cf11e2c2938f0d1003d9f912f5f91f'),
  (248, 'samesa-canggu', 'best_for', (select count(*)::int from venues where slug = 'samesa-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '91564d012e739f09d4dcaa8fabb7ca96'), md5('Communal Italian set-menu dinners at one long shared table, one seating a night') = '25b0e9a6c4b75567e4bfb7a39127fe98'),
  (249, 'santanera', 'why_its_here', (select count(*)::int from venues where slug = 'santanera' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b562f4242df1970cd2e33cd73d47e915'), md5('On Jl. Tanah Barak, Santanera pairs a Latin American dining room with a rooftop bar. The sharing menu mixes Latin flavours with European technique and local ingredients. Contemporary artwork, a big seated room and a late-night bar make a full evening of it.') = '703ceea9268e789b20c462b6b111e363'),
  (250, 'santanera', 'best_for', (select count(*)::int from venues where slug = 'santanera' and status = 'active' and publication_status = 'published' and md5(best_for) = 'da21a54132c86d604ce3ba3d998c765b'), md5('A special evening of rooftop cocktails and shared plates, as a date or with a group') = '79d2cc60215653cd4df468f33c0739f4'),
  (251, 'satu-satu-coffee-company', 'why_its_here', (select count(*)::int from venues where slug = 'satu-satu-coffee-company' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '32fbff8db43f8dc0b7361ad931c15a19'), md5('Built on the Sudana family''s Balinese single-origin beans, roasted in-house, Satu-Satu is a family-run specialty coffee company in Berawa. The bright white space is eco-minded. A simple all-day menu of bowls, sandwiches and smoothies feeds the post-surf crowd.') = '58fcc5a5a07f14448fd50e4998b9d18a'),
  (252, 'satu-satu-coffee-company', 'best_for', (select count(*)::int from venues where slug = 'satu-satu-coffee-company' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e4193cbcdc2b24552eac696daab6c657'), md5('Well-pulled espresso from Indonesian single origins for coffee lovers, or a healthy breakfast or lunch bowl after a surf') = 'c319948dec8750878d3dc7da885b7bc5'),
  (253, 'satu-satu-coffee-company', 'not_for', (select count(*)::int from venues where slug = 'satu-satu-coffee-company' and status = 'active' and publication_status = 'published' and md5(not_for) = '786886e2befa8a5e40abbcd4f4918ac3'), md5('An evening out: coffee and brunch here are daytime affairs') = '7f72fb990679691ba636d1ffada6b5c6'),
  (254, 'saya-club', 'why_its_here', (select count(*)::int from venues where slug = 'saya-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c572bc854f5ebc506656573020ab8fff'), md5('Saya Club combines a gym and coworking space in Berawa. There is personal training, and classes in pilates, reformer, boxing and yoga. On site are an ice bath, a sauna, a pool and a cafe-bar.') = '5206d1ec1d10e1bbe6745f94d24d1c70'),
  (255, 'saya-club', 'best_for', (select count(*)::int from venues where slug = 'saya-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '6335056f5c23fe2f6cf68cf4337c3069'), md5('Training') = 'cf270e40d273f9e7fd7c3061729060c3'),
  (256, 'secana-rooftop-bali', 'why_its_here', (select count(*)::int from venues where slug = 'secana-rooftop-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b62719cc2367ea3066f53f75a2f95838'), md5('On top of the Secana Beachtown resort in Berawa, Secana Rooftop is a pool bar and restaurant open from morning to 11pm. There are daybeds by day, the menu moves between Mediterranean and comfort cooking, and DJs play sunset sessions on Fridays and Sundays.') = '8bf3c0a031a4ffdc9526f72c39f08c82'),
  (257, 'secana-rooftop-bali', 'best_for', (select count(*)::int from venues where slug = 'secana-rooftop-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '2e4f4ebf2044fc1b7ba7c10d40d41a8f'), md5('A daybed by the rooftop pool, or a DJ sunset on Friday or Sunday') = '06b9a9bd70d695161b38144a333cd534'),
  (258, 'secret-spot-bali', 'why_its_here', (select count(*)::int from venues where slug = 'secret-spot-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2eebf1c526ec6c9b2abb301ff479d7b3'), md5('Secret Spot is a fully plant-based cafe serving vegan food from breakfast through dinner: croissants, bowls, curries and ramen. The coffee is roasted weekly on the island, with chicory as an alternative. Monday is pasta night, with live jazz.') = '38cd1cd04df35570e12a7dd1df9fffaf'),
  (259, 'secret-spot-bali', 'best_for', (select count(*)::int from venues where slug = 'secret-spot-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '62675344d42d805870072eff79a85f42'), md5('Vegan breakfast or brunch of plant-based croissants and pastries, with island-roasted coffee') = '053d01da6f9be5694dd9bc9ed147ad7e'),
  (260, 'secret-spot-bali', 'not_for', (select count(*)::int from venues where slug = 'secret-spot-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '8ce9b7c5f016cffc9fa92a81c41db899'), md5('Meat or seafood eaters, or a fast grab-and-go stop: the menu is fully plant-based') = '76a1a83a70e944b434fb631d65b01be2'),
  (261, 'seseh-general-store', 'why_its_here', (select count(*)::int from venues where slug = 'seseh-general-store' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4a5b15a4480014608167f5ab64a2b183'), md5('Melbourne coffee culture comes to coastal Cemagi and Seseh at Seseh General Store, an Aussie-owned corner cafe a short step from the beach. It does well-made breads, sandwiches and salads, and has the feel of a community hub.') = '18d92f5b202dc0a3f630c6460223b542'),
  (262, 'seseh-general-store', 'best_for', (select count(*)::int from venues where slug = 'seseh-general-store' and status = 'active' and publication_status = 'published' and md5(best_for) = '3b84e15640979c8890a83e58cb2f760b'), md5('A morning coffee and pastry, a casual sandwich-and-salad lunch, or a stop after the beach') = '5a607e42028588a092bc562ca8bafd58'),
  (263, 'seseh-general-store', 'not_for', (select count(*)::int from venues where slug = 'seseh-general-store' and status = 'active' and publication_status = 'published' and md5(not_for) = 'f07db139ba8a1822d0dad484dd37834e'), md5('A sit-down dinner or a formal evening out, because the food is breads, sandwiches and salads') = '7adcd513a392b4a3ba915ef6e3569fc9'),
  (264, 'shelter-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'shelter-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b59910a50580da5b75e907dee657c645'), md5('Shelter, a wood-fired Middle Eastern and Mediterranean restaurant in Pererenan, is built inside a Balinese joglo with open, plant-filled architecture. A UK chef runs the kitchen, and a rotating calendar brings BBQs and vinyl DJ nights. Booking is recommended.') = 'de434dbddb6375564791de35e95ad6fe'),
  (265, 'shelter-restaurant', 'best_for', (select count(*)::int from venues where slug = 'shelter-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = '05b393d41bb2b53b0a886727e89ba8df'), md5('Special occasions, date nights and group dinners, booked ahead') = 'a63a018053ae6dda3a69ad0a34e28dbf'),
  (266, 'shelter-restaurant', 'not_for', (select count(*)::int from venues where slug = 'shelter-restaurant' and status = 'active' and publication_status = 'published' and md5(not_for) = '1c2b3c96e2a51adba2b41ad4db7871b6'), md5('A quick walk-in lunch or a solo laptop session, because reservations are recommended') = '7b5fd6047c7e6dc746dc753e14faec1f'),
  (267, 'shichirin-japanese-restaurant-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'shichirin-japanese-restaurant-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cadb67aaac0c915531ff9bc1ab04e126'), md5('Shichirin brings Japanese grill cooking to Berawa as part of the Wonderspace group. The menu has teppanyaki, gyukatsu and izakaya plates. Sushi and sashimi are on it too. The house dishes are black cod in saikyo miso and breaded Santuri wagyu.') = '5f4d5b31ff76b80ff93fc09d70560a05'),
  (268, 'shosan-holistic-spa-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'shosan-holistic-spa-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cae1c0a3af84386cf1e98acf936953fd'), md5('Shosan, a wellness spa in Canggu, takes bookings through Fresha. Its published list covers head massage and traditional massage, and the 90-minute Shosan Signature Massage costs 1100K IDR.') = '45c1391bb0cce7b16a7960073e578201'),
  (269, 'shosan-holistic-spa-canggu', 'best_for', (select count(*)::int from venues where slug = 'shosan-holistic-spa-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '1a510b0da01dd9d9bb63391a761453a7'), md5('A head massage booked the same day') = '8877f02b0bcbe94fb85a291531963c26'),
  (270, 'shosan-holistic-spa-canggu', 'not_for', (select count(*)::int from venues where slug = 'shosan-holistic-spa-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '89331ac475c68778c799f1c0ba4228d4'), md5('A budget massage: the published list starts at 1100K IDR') = '464f19b5d31c188af42b3db819397a37'),
  (271, 'sia-grill-and-seafood-bar', 'why_its_here', (select count(*)::int from venues where slug = 'sia-grill-and-seafood-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '54aa43b82fcb0a0df61795418028f551'), md5('SIA is a casual seafood and grill bar on the Canggu Shortcut. Fresh fish meets Balinese ingredients and Asian influences, and there is a cocktail programme.') = '07df42f5009cf0b8ddd045b4a0cc11fa'),
  (272, 'sia-grill-and-seafood-bar', 'best_for', (select count(*)::int from venues where slug = 'sia-grill-and-seafood-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '05c502a1cf51dd3774806d538f6c5db4'), md5('Fresh seafood and grill plates with cocktails on the Canggu Shortcut') = '77acad223f476e5bf5a027ac9528bbb5'),
