  (274, 'skool-kitchen', 'why_its_here', (select count(*)::int from venues where slug = 'skool-kitchen' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '52acf3989a62356f5595b8dc9408aafe'), md5(U&'SKOOL Kitchen is an open-flame kitchen on Jl. Pura Dalem that cooks meats and seafood over wood and charcoal. Dinner only, from 5pm: a tasting menu, \00E0 la carte plates and cuts priced by weight. It shares an address with The Lawn Canggu, another Project Black venue.') = '13d81bcf7a0c1849bbbc03eb515b85b7'),
  (275, 'skool-kitchen', 'best_for', (select count(*)::int from venues where slug = 'skool-kitchen' and status = 'active' and publication_status = 'published' and md5(best_for) = '01c40e81fde8f6da0324c56cd7192a5b'), md5('A special-occasion or date-night dinner by the beach, with drinks') = '1fa8c60ea0e125ee43d759db031b86f4'),
  (276, 'skool-kitchen', 'not_for', (select count(*)::int from venues where slug = 'skool-kitchen' and status = 'active' and publication_status = 'published' and md5(not_for) = 'edfe65f23a48534ab20db79940bf9d5b'), md5('Daytime plans, since it opens at 5pm daily') = 'f72c8c47b54d37ed1ec0b7f74362e65d'),
  (277, 'smoke-grill-master-and-barbeque-bali', 'why_its_here', (select count(*)::int from venues where slug = 'smoke-grill-master-and-barbeque-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ce13a0797753fa012042b41371fd695e'), md5('SMOKE cooks open-fire barbecue at Echo Beach, with seating outdoors, in a tent or indoors. It also has a private backyard barn and a chef''s table, for groups of ten or more booked 48 hours ahead.') = 'dfd1044e2e2f1bcb1dc2cfc467b3e561'),
  (278, 'smoke-grill-master-and-barbeque-bali', 'best_for', (select count(*)::int from venues where slug = 'smoke-grill-master-and-barbeque-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '6783c946a4bbb6a214c418566750e9fc'), md5('Open-fire barbecue at Echo Beach, in the tent, indoors or in the garden') = '9deb845eb271620e238b9a34d713306c'),
  (279, 'spring-spa-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'spring-spa-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '685e8aaf4ea8b3405f87a9b91ba13a45'), md5(U&'Spring Spa''s Batu Bolong branch belongs to an island-wide chain and sits a short walk from Canggu''s caf\00E9s. It does brisk, well-priced manicures, waxing, massage and facials in a bright, clean salon.') = '356c1de4898abe9e9af2025d2eaf5d48'),
  (280, 'spring-spa-canggu', 'best_for', (select count(*)::int from venues where slug = 'spring-spa-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '6eccfa9873b552dc35ddf189d761a285'), md5('A walk-in mani-pedi or a quick massage between beach and brunch, without a hotel-spa booking') = '85f6a5fcdcbf54de527f9d91f8ccda70'),
  (281, 'surya-fitness-gym', 'why_its_here', (select count(*)::int from venues where slug = 'surya-fitness-gym' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8ba6e7e7fb803e75458247fead0a83b5'), md5('A gym and fight club in Pererenan, Surya Fitness uses Life Fitness, Hammer Strength and TechnoGym equipment. The fight club runs boxing, Muay Thai, pad work and sparring. On site are a stretching rooftop and a cafe, plus billiards.') = 'fd02d1ce5afaddf4364ba097ed4f4582'),
  (282, 'surya-fitness-gym', 'best_for', (select count(*)::int from venues where slug = 'surya-fitness-gym' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b648a6c8c9942b9c52d4b67fad71bcbe'), md5('Lifting and striking under one roof, with air conditioning, water, towels, showers and lockers in the membership') = '541e7a7f99fbf22ac96d46d8930428ba'),
