  (284, 'sushimi-bali', 'best_for', (select count(*)::int from venues where slug = 'sushimi-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '4d29e0795d282634e1343e3c9db8c9b8'), md5('Casual sushi off the train, with friends, on your own or with a group of mixed diets') = '5339d7b3f4708ba5de539812f35a352f'),
  (285, 'sushimi-bali', 'not_for', (select count(*)::int from venues where slug = 'sushimi-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a7088b6f805a9e2438ec1e1f167e3002'), md5('A formal or high-end omakase, a quiet intimate dinner or a sea view, because this is a casual sushi train') = '7f0e7bd3668595f55ed483ce34740036'),
  (286, 'swarna-spa-and-wellness', 'why_its_here', (select count(*)::int from venues where slug = 'swarna-spa-and-wellness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e9a35d2e235a0832a20ed2d93280e64f'), md5('Swarna does Balinese and hot stone massage and facials at its spa and wellness venue in Pererenan. Its house thermal ritual combines a hot plunge and cold immersion with an infrared sauna.') = '7daa872130721b618fa66fef9db4fe6b'),
  (287, 'swarna-spa-and-wellness', 'best_for', (select count(*)::int from venues where slug = 'swarna-spa-and-wellness' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd6dce9cf72ceeefa8f121e7043183be5'), md5('A full pampering session of massage, facial and hot-cold therapy in one calm venue') = 'e30c009b2c4d4a3a38b7f238b6f1bdf3'),
  (288, 'the-avocado-factory', 'why_its_here', (select count(*)::int from venues where slug = 'the-avocado-factory' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '850dbc3188405ed4970a49a816da67ac'), md5('Avocado runs through the whole menu at The Avocado Factory, a cafe. Dishes run from truffle eggs benedict to avo pancakes and avocado basque cheesecake, in an eco-conscious build.') = 'd81dfe584a66a9e40007bdf7c5fff00d'),
  (289, 'the-avocado-factory', 'best_for', (select count(*)::int from venues where slug = 'the-avocado-factory' and status = 'active' and publication_status = 'published' and md5(best_for) = '577274bb9081fe06f4ec337fae094662'), md5('Avocado and brunch lovers by day, or burgers late into the evening') = 'dac6cabcafc69acbf2eea75c4738b099'),
