  (291, 'the-canggu-studio-canggu', 'best_for', (select count(*)::int from venues where slug = 'the-canggu-studio-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'af9a1c5c71f42fbe0c67c02ef48cd783'), md5('Low-impact reformer Pilates in an intimate class rather than a big gym') = 'ab9d9f2b8453407ede3ed930d262decf'),
