  (293, 'the-canggu-studio-yoga-canggu', 'best_for', (select count(*)::int from venues where slug = 'the-canggu-studio-yoga-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '9f55e79c85a0716d92ea9bd6e87ebf23'), md5('An intimate yoga class instead of a big drop-in hall') = 'a38388841eeba3e63f89622a65791929'),
