  (295, 'the-flow-bali', 'best_for', (select count(*)::int from venues where slug = 'the-flow-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '510f8c77b6056eda0794c0ac49ff09af'), md5('Char-grilled Mediterranean-Asian plates and prime cuts in Pererenan') = '03c39f01e3172a8990f48be9e301f2bf'),
  (296, 'the-lawn-canggu-beach-club', 'why_its_here', (select count(*)::int from venues where slug = 'the-lawn-canggu-beach-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '21966e776e78fbb95585d190abcab89d'), md5('Right on the black sand of Batu Bolong Beach, The Lawn is a beach club with an ocean-facing infinity pool and daybeds. Its bar-restaurant runs sunset sessions with DJs over the Indian Ocean, as daytime lounging shifts into golden-hour drinks.') = '58b538cfdc5a76c45201e3ab89fded2b'),
  (297, 'the-lawn-canggu-beach-club', 'best_for', (select count(*)::int from venues where slug = 'the-lawn-canggu-beach-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '0cfb05306dd2634081851ec5996e013f'), md5('Sunset cocktails from a daybed, or an easy day between surf sessions') = 'e1fc9fa482c799ac50aa4ad562d03795'),
  (298, 'the-lawn-canggu-beach-club', 'not_for', (select count(*)::int from venues where slug = 'the-lawn-canggu-beach-club' and status = 'active' and publication_status = 'published' and md5(not_for) = 'd9bae66c964ae32eff77ed91520fe8c7'), md5('A quick, cheap breakfast stop: this is a full beach club') = 'c9c2a33aaaa9d0e0281069493a7b3de5'),
  (299, 'the-loft-bali', 'why_its_here', (select count(*)::int from venues where slug = 'the-loft-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '007ddce0fdf69879652fc2177be1e2d4'), md5('The Loft serves specialty coffee and a large plant-based selection at its Bondi-inspired all-day brunch cafe on Batu Bolong. The food leans to healthy breakfast staples, bowls and toasts.') = '8ec3b8d5c20aea523584a3686a1d0735'),
  (300, 'the-loft-bali', 'best_for', (select count(*)::int from venues where slug = 'the-loft-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '5c06ac68082860f6f2dfe07915a9ccc9'), md5('A slow brunch after the beach, specialty coffee with a laptop, or a plant-based, healthy breakfast') = 'be2fd6459286ae5395e0e6cc856b06dc'),
  (301, 'the-loft-bali', 'not_for', (select count(*)::int from venues where slug = 'the-loft-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '37964761b4a14e2af93a5885bb377f9f'), md5('A quiet, non-touristy local spot or a traditional Balinese meal: the cafe is Bondi-inspired, with healthy breakfast staples') = 'fce1ecb61cb6d8fda22bee419a6dceb7'),
  (302, 'the-shady-shack', 'why_its_here', (select count(*)::int from venues where slug = 'the-shady-shack' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a8eab9256db1db9a3d7e5b6c4697ac2e'), md5('From the team behind Betelnut, The Shady Shack is an all-day vegetarian and vegan cafe looking over the Berawa rice fields. The wholefood menu is big: all-day breakfast, smoothies, salads, share plates and vegan desserts, in a leafy, open setting.') = '0d08ed39527f513afb153d0c602dbed9'),
  (303, 'the-shady-shack', 'best_for', (select count(*)::int from venues where slug = 'the-shady-shack' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e6133f1d4c93116bae66c2c9e303bbe6'), md5('Plant-based eaters, from a healthy brunch after a surf to an early dinner with a rice-field view') = 'e80296ec84c2602b89041b3d3457bfc3'),
  (304, 'the-shady-shack', 'not_for', (select count(*)::int from venues where slug = 'the-shady-shack' and status = 'active' and publication_status = 'published' and md5(not_for) = '385185c328fd7377de64642307c96739'), md5('Diners set on meat or seafood, because the menu is entirely vegetarian and vegan') = 'd743a4435fb6b7d9f5ac3e32bfb2783f'),
  (305, 'the-shampoo-lounge-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'the-shampoo-lounge-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'bc15e5d7fe24a7a69b200ca03ca6e709'), md5('HairShop is the Canggu branch of a Bali hair-salon brand, in Tegal Gundul Square on Jl. Pantai Berawa. English-speaking stylists do cuts, colour and blow-outs in an air-conditioned space.') = '00dc171d504eb9819b3339fae617d14c'),
  (306, 'the-shampoo-lounge-canggu', 'best_for', (select count(*)::int from venues where slug = 'the-shampoo-lounge-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '9279b24ce3e4d5e85943b8223a782845'), md5('A haircut or colour on the road, booked easily by WhatsApp') = '2c26e4fa3a8613aa9b483efd3a9607fa'),
  (307, 'the-slow', 'why_its_here', (select count(*)::int from venues where slug = 'the-slow' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '558d9f147c87222dfe978f4631908d98'), md5('The restaurant, bar and gallery inside The Slow, a design-led boutique hotel on Batu Bolong. The kitchen is internationally inspired and runs all day, and the room doubles as an art and events space. It works for breakfast as well as an evening out.') = '577bc9d3317b7d359748ea2b72174df5'),
  (308, 'the-slow', 'best_for', (select count(*)::int from venues where slug = 'the-slow' and status = 'active' and publication_status = 'published' and md5(best_for) = '29c0432f8b16dd2b5416a80e9a299bb8'), md5('A design-led brunch or dinner inside The Slow hotel on Batu Bolong') = 'e782ec32dc23cbb9480228148a72d727'),
  (309, 'therapy-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'therapy-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0ea53ed24580e2127cf4aa5754cbfaf6'), md5('The Batu Bolong flagship of the Therapy group, open 9am to 8pm, with massage, facials and beauty treatments in a calm space.') = '98dacc39735f778572cc24c9e6bdbca9'),
