  (311, 'therapy-day-spa-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'therapy-day-spa-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd85ba22f0ea43e51abe82052a0e59fe9'), md5('Therapy Day Spa on Jl. Pantai Pererenan is built around plant-derived rituals that are toxin-free and cruelty-free. Massages, facials, body scrubs and scalp treatments run in a calm setting.') = 'e59136b353a707e1789a05a7520b1da6'),
  (312, 'therapy-day-spa-pererenan', 'best_for', (select count(*)::int from venues where slug = 'therapy-day-spa-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = '8e29097777bfe5298b0dc3854a4b4bd2'), md5('A natural, clean-ingredient massage or facial in a calm Pererenan setting') = 'c2324d2857bab5ef6eaceaa01fed425b'),
  (313, 'therapy-hair-spa-canggu-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'therapy-hair-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '93a2d14c3cb76e06fc1f9beb6e8c5123'), md5('The Therapy group''s Canggu salon, open 9am to 8pm, pairs hairdressing with spa-style facials and massage. On the hair side there are cuts, colour and blow-outs.') = '84c3d4873db4a8dc52fc81e71076fbd5'),
  (314, 'therapy-hair-spa-canggu-canggu', 'best_for', (select count(*)::int from venues where slug = 'therapy-hair-spa-canggu-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '5f0708ec435712ecda90540a7a832edb'), md5('Hair and beauty under one roof, near Batu Bolong') = '7cd3f5c329b51c999f47eb2bb5b12175'),
  (315, 'top-gym', 'why_its_here', (select count(*)::int from venues where slug = 'top-gym' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c8fb7310c043b2082831862d7ee8003e'), md5('A 400-square-metre boutique gym near Batu Bolong, Top Gym has rice field views and TechnoGym equipment throughout. The recovery area has a panoramic terrace, two ice baths, a sauna, a smoothie bar and loungers.') = 'b0a579a090091039092ee009bdd01647'),
  (316, 'top-gym', 'best_for', (select count(*)::int from venues where slug = 'top-gym' and status = 'active' and publication_status = 'published' and md5(best_for) = '9db98048f936bd03fa52bec8e72a2473'), md5('Training and recovery in one stop, with group classes in stretching, yoga, pilates, functional training, boxing and dance') = 'ef4a8cecada357ca21d1b019aee8f462'),
  (317, 'touche-cafe-and-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'touche-cafe-and-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cc2af8425c3d3ee9df78ee7bd411ff38'), md5(U&'Near Pererenan beach, Touch\00E9 keeps all-day cafe hours from early morning to late, with design-led interiors and an urban-leaning menu.') = '1377b5ddb78d828d3054e9416d75e7d9'),
  (318, 'touche-cafe-and-restaurant', 'best_for', (select count(*)::int from venues where slug = 'touche-cafe-and-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ab3fb574765b836d83563f67a26e6554'), md5('Brunch among design-led interiors, a daytime coffee with the laptop, or a casual meal') = '223b1693965abae38896b46efd921ccb'),
  (319, 'touche-cafe-and-restaurant', 'not_for', (select count(*)::int from venues where slug = 'touche-cafe-and-restaurant' and status = 'active' and publication_status = 'published' and md5(not_for) = '97aa7b858ae21399e80b0d6760e44767'), md5('A beach-club scene or a big group party: it is an all-day cafe') = '7e8a690b4487e1a30118bb86fe675ae4'),
  (320, 'tropical-nomad', 'why_its_here', (select count(*)::int from venues where slug = 'tropical-nomad' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd00e83ac72caefe087142f58918a42a1'), md5('Tropical Nomad is a coworking space on the Canggu shortcut with an open-air cafe built in that looks over rice fields and a garden. It is made for eating, sitting with a laptop and staying a while.') = '17fbd97d19a4f628c4aac8846725f753'),
  (321, 'tropical-nomad', 'best_for', (select count(*)::int from venues where slug = 'tropical-nomad' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd5122b5fec4dd3e00167adcf36856ced'), md5('Digital nomads and remote workers after fast wifi and big shared tables, or a casual daytime coffee') = '2984bb29a7fdb7c3215490f474f31b27'),
  (322, 'tropical-nomad', 'not_for', (select count(*)::int from venues where slug = 'tropical-nomad' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c4e599fa28a27303a1e40c8866e4e8ee'), md5('A romantic dinner or a special-occasion night out, because this is a coworking space with a cafe') = 'bf3e0b7ec958e122e56365e14e37c67f'),
  (323, 'two-face-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'two-face-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0b637d1fa79cb7675205a6b30d262b30'), md5('Well-made coffee and creative brunch dishes are the focus at TWO FACE, a specialty coffee and brunch cafe on Jl. Munduk Catu in Canggu. It has a community feel.') = '3c7bfbf587c2f5db2000222467b3649a'),
  (324, 'two-face-canggu', 'best_for', (select count(*)::int from venues where slug = 'two-face-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'fb2a73c1c36432c61aaa735ed0671d5f'), md5('A morning brunch and specialty coffee in a welcoming space') = 'ac105dc2d27f157e46204d1ad7afe15b'),
  (325, 'udara-bali', 'why_its_here', (select count(*)::int from venues where slug = 'udara-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8f8d3866d7f9a29d217fa5942add074c'), md5('Organic Ocean, the plant-forward restaurant at the Udara wellness retreat in Seseh, is open daily to guests and visitors. The cooking is healthy and conscious of community and earth.') = 'a8752fd86ce649b3c3acf7f72fb6e3d9'),
  (326, 'udara-bali', 'best_for', (select count(*)::int from venues where slug = 'udara-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ba55f6d2a0357330c420071658404ed9'), md5('Health-minded diners after a quiet, restorative and organic meal near the beach') = 'bdff68ae8e49d9787b3d708a65a2b7a7'),
  (327, 'udara-bali', 'not_for', (select count(*)::int from venues where slug = 'udara-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '97ccf20e01e58af7907154c8c0358c13'), md5('A lively nightlife scene or a heavy meat-and-cocktails night out: the kitchen is plant-forward') = '0e2d93e9c2ffa95fd5e922bc2dc5bdf2'),
  (328, 'udara-bali-yoga-detox-and-spa-organic-ocean', 'why_its_here', (select count(*)::int from venues where slug = 'udara-bali-yoga-detox-and-spa-organic-ocean' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c1863e93420d1dc1e6d4919339920b44'), md5('At Seseh Beach, Udara Bali is a yoga, detox and wellness retreat resort for adults only (14+). It has five ocean-view yoga shalas and Quantum Sound Domes for sound healing. Its spa has a water-healing pool; there are seawater pools too, and the plant-forward Organic Ocean restaurant.') = '5e81e00bdd679ae5d4075a6aac752f72'),
  (329, 'udara-bali-yoga-detox-and-spa-organic-ocean', 'best_for', (select count(*)::int from venues where slug = 'udara-bali-yoga-detox-and-spa-organic-ocean' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a725cf3750659bc0f05c72ee011d9e34'), md5('A yoga or detox retreat, sound healing or a spa day in a quiet adults-only setting by the ocean') = '637e10d4ce65050aab6366e1d4086f74'),
  (330, 'udara-bali-yoga-detox-and-spa-organic-ocean', 'not_for', (select count(*)::int from venues where slug = 'udara-bali-yoga-detox-and-spa-organic-ocean' and status = 'active' and publication_status = 'published' and md5(not_for) = '69d1f0db20cce84b0a8c26eb1c211a34'), md5('Families with young children or a lively town-centre base, because it is adults-only (14+) and out at Seseh Beach') = 'a0d2139df8cf5f3bd1ab2be2d5fe74ee'),
  (331, 'ulekan-berawa', 'why_its_here', (select count(*)::int from venues where slug = 'ulekan-berawa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '63229d20ccb8d94ff5f2e061bdee93ff'), md5('Ulekan, a sit-down Indonesian restaurant in Berawa, cooks dishes from across the archipelago. Spices are ground by hand and there is no MSG or palm oil; ingredients come from small-scale farmers and fishermen. Tables sit in a fairy-lit garden.') = '2eea185a226364b7f86bd5e886cfa30a'),
  (332, 'ulekan-berawa', 'best_for', (select count(*)::int from venues where slug = 'ulekan-berawa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c5669ad8a742576bbb60da752f262705'), md5('A sit-down dinner of classic Indonesian dishes, shared as a group or as an accessible introduction to the cuisine') = '70de2221ef6eabe9f4c51bbeb12a37fa'),
  (333, 'victory-fitness-club', 'why_its_here', (select count(*)::int from venues where slug = 'victory-fitness-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5d8089b61f7fc5e3be2803a40b4ad972'), md5('Open daily 07:00-20:30, Victory Fitness Club is a budget gym at Jl. Pantai Pererenan No.89. Equipment spreads over two floors, with a punching bag and loan gloves upstairs and a smoothie bar below. An ice bath and sauna are on site.') = 'd27449d78d7c0c24fa141d160a68f231'),
  (334, 'victory-fitness-club', 'best_for', (select count(*)::int from venues where slug = 'victory-fitness-club' and status = 'active' and publication_status = 'published' and md5(best_for) = 'fee0cf79fde2c59435219e031e9ec9ca'), md5('Cheap, no-frills lifting with ice bath and sauna, at around EUR 3 for the day') = '962be38ddad0049241945ce4819f9508'),
  (335, 'wanderlust-fitness-village-canggu', 'best_for', (select count(*)::int from venues where slug = 'wanderlust-fitness-village-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'cb6bb7c4a45d5d7a5424aade7a695694'), md5('A full day of varied training in one spot, with a community feel') = '8839fa7b132cb3480d28345384c4c994'),
  (336, 'warung-local', 'why_its_here', (select count(*)::int from venues where slug = 'warung-local' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '066d58c79a301f6c39abb683e2be6f08'), md5('Warung Local is a semi-open Indonesian warung on the Batu Bolong strip, open daily 10am to 10pm. The kitchen is Halal and cooks local staples such as nasi campur, nasi goreng and satay, and there is an outdoor seating section.') = '30870dcaf26a00f6c809805995716c95'),
  (337, 'warung-local', 'best_for', (select count(*)::int from venues where slug = 'warung-local' and status = 'active' and publication_status = 'published' and md5(best_for) = '3711266ef30047c0df3d5073463753e6'), md5('Halal diners after familiar local staples, at lunch or a casual dinner in central Batu Bolong') = 'dc67def068debc9d606ec1519c245a33'),
  (338, 'warung-local', 'not_for', (select count(*)::int from venues where slug = 'warung-local' and status = 'active' and publication_status = 'published' and md5(not_for) = '8aeb216c8f0ad5840b4cd04d9b4df0d9'), md5('Pork dishes or a quiet, no-scene warung: the kitchen is Halal and it sits on the Batu Bolong strip') = '950b2350e4ed6f4e50ae6b7c1569f534'),
  (339, 'warung-nonii', 'why_its_here', (select count(*)::int from venues where slug = 'warung-nonii' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '96727fc2c12d7c4f06037b696bfef5ca'), md5('Just up from the beach on Jl. Pantai Batu Bolong sits Warung Nonii, also written Waroeng Nonii, an affordable Indonesian warung. It is open from breakfast through dinner, nasi campur is the house plate, and takeaway is available.') = '7a3e53f8a8703556aac122de8ceb473c'),
  (340, 'warung-nonii', 'best_for', (select count(*)::int from venues where slug = 'warung-nonii' and status = 'active' and publication_status = 'published' and md5(best_for) = '93e7573983888ec2e5182e65937f7b94'), md5('A cheap, easy local meal at any time of day, including a low-key dinner straight off the plane') = 'df8c20c7e391542d19b9ae8b4a3ea8f0'),
  (341, 'warung-sika', 'why_its_here', (select count(*)::int from venues where slug = 'warung-sika' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ffa4840e6e03d3dedf71ddd9c6e9383a'), md5('Family-run Warung Sika serves nasi campur, open daily 9am to 9pm. It is point-and-pick: you choose rice, then add vegetables and meats from the display.') = '0b42d6fd89d7212203ade7b2dd55e167'),
  (342, 'warung-sika', 'best_for', (select count(*)::int from venues where slug = 'warung-sika' and status = 'active' and publication_status = 'published' and md5(best_for) = '30be2f043773e6b992c75c73dbb759bd'), md5('Solo diners and first-timers after a cheap, build-your-own nasi campur lunch in an English-friendly setup') = 'b0e99c0cb8c8e19d1f12bb8c25535dcb'),
  (343, 'warung-sika', 'not_for', (select count(*)::int from venues where slug = 'warung-sika' and status = 'active' and publication_status = 'published' and md5(not_for) = '06d860f85ec71ef64fba4d4528e04b6e'), md5('Table service or a quiet sit-down dinner, because the room is busy and canteen-style') = 'ca9dff2ad3c5fc79a5d2c5723fef6d3e'),
  (344, 'woods-bali', 'why_its_here', (select count(*)::int from venues where slug = 'woods-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b199265737704d441f3bf733e2e069df'), md5('Built entirely from reclaimed wood, Woods is a rustic Pererenan restaurant cooking a Mediterranean menu in a warm, greenery-filled chalet. It runs as a cafe by day and a dinner room by night, with live jazz and vinyl evenings.') = '0e63fac8fa29b5dec435b63d14ce6341'),
  (345, 'woods-bali', 'best_for', (select count(*)::int from venues where slug = 'woods-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '2f2e0c5d2a85716ca82f0d5be6570f97'), md5('A cosy dinner or a date night, or a group evening with live music') = 'abdf4dc3fe229e9d61f7d546812956d4'),
  (346, 'workmates-coworking-space-and-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'workmates-coworking-space-and-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '41e8a3913c435bae4bf0f0b03055a004'), md5('Workmates is a coworking space and cafe in Canggu, part of the Wonderspace group. Desks and fast wifi come with a poolside view. The kitchen does chicken parmigiana, Indonesian plates and bowls.') = 'b7ed00522a08b7d43c62d04d45c85d7b'),
  (347, 'wrong-gym-pererenan', 'why_its_here', (select count(*)::int from venues where slug = 'wrong-gym-pererenan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1d0cf61ddb39fd558bc43c3568a78e36'), md5('Opened in 2023 on Jl. Pantai Pererenan, The Wrong Gym is an all-inclusive gym and lifestyle club. It has a large outdoor training area, a functional jungle gym and fitness classes. Recovery means sauna, ice bath, pool, yoga and spa.') = '933bb8abbffe2b7950649a538687dc57'),
  (348, 'wrong-gym-pererenan', 'best_for', (select count(*)::int from venues where slug = 'wrong-gym-pererenan' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ad46859acac727f213c1596807c82c7d'), md5('Digital nomads and fitness-focused travellers on a longer Pererenan stay, after a full-service gym with classes and recovery') = 'd498d6165685a17e027c1b0eb4a7dc33'),
  (349, 'wrong-gym-pererenan', 'not_for', (select count(*)::int from venues where slug = 'wrong-gym-pererenan' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a2cb0e6fc0fec6204f6484db16d880e4'), md5('A budget drop-in or a purely passive spa visit: the club is all-inclusive and built around training') = '9529211fbf11e80ccd842f77f5c16630'),
  (350, 'yema-kitchen', 'why_its_here', (select count(*)::int from venues where slug = 'yema-kitchen' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9b77fa55e071147e3fea33a22bc1897e'), md5(U&'A caf\00E9 and restaurant on Jl. Tanah Barak, Yema Kitchen runs as a caf\00E9 by day and a bar by night. It calls itself Mediterranean but cooks closer to North African and Levantine: tajine, couscous, pastilla, shawarma and pide.') = '11ee708ed9be2571e4b427e802f341bc'),
  (351, 'yema-kitchen', 'best_for', (select count(*)::int from venues where slug = 'yema-kitchen' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f523cc99eb88199e6fcc8d004e3ad7f2'), md5(U&'Tajine, couscous or pastilla, at the caf\00E9 by day or the bar by night') = 'ade2dd324b0f26a23fb8535ed7fc2bf9'),
  (352, 'yuki-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'yuki-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fcc30c136a8e4c4c695a6dd990312a7b'), md5('Steps from Batu Bolong beach, YUKI is a modern Japanese izakaya. It serves fusion sushi, wood-fired specialties and house cocktails.') = '5b754ec2a9f82ed257fc4f402776f04a'),
  (353, 'yuki-canggu', 'best_for', (select count(*)::int from venues where slug = 'yuki-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '9e32c758b0b0e2fdba3419ab58af5439'), md5('A date night, special occasion or group dinner with cocktails') = '98f67a1e91ca84c0384d0cd88c28758b'),
  (354, 'yuki-canggu', 'not_for', (select count(*)::int from venues where slug = 'yuki-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '50c610c4d47ced08e96f6ab52782e258'), md5('A budget meal or a walk-in at any hour: reservations are recommended') = '2fc228fb3afefda4f46e41db65c4b5b2'),
  (355, 'zin-cafe-canggu', 'why_its_here', (select count(*)::int from venues where slug = 'zin-cafe-canggu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f868d329af8a0a5d0aa06a6bbf5b7017'), md5('ZIN is an open-air bamboo cafe near Nelayan Beach that doubles as a free coworking space. Most tables have power outlets, the wifi is fast and there is a quiet upper room. The coffee is organic and roasted in-house.') = 'ff5534b3aabd947e1feaff99b5a95d6f'),
  (356, 'zin-cafe-canggu', 'best_for', (select count(*)::int from venues where slug = 'zin-cafe-canggu' and status = 'active' and publication_status = 'published' and md5(best_for) = '408c4f4b0a154a0c48e494b8bfe127a1'), md5('Remote workers and digital nomads working over breakfast and coffee, or a calm, healthy meal near the beach') = '5f396ca67ada6a717b37605a4e1783a7'),
  (357, 'zin-cafe-canggu', 'not_for', (select count(*)::int from venues where slug = 'zin-cafe-canggu' and status = 'active' and publication_status = 'published' and md5(not_for) = '28250101b7e161426260fbea3b6e0bc2'), md5('A lively bar scene or a fully quiet fine-dining room: people come here to work') = '0d56e537ed2bed5368ffac8056faf0de')
) as t(n, slug, field, rows_matched, text_ok)
